window.BANQUE_INFINI = {"module":"annee-2/theorique/semestre-1/musculo-squelettique","titre":"Conditions Musculo-squelettiques","sources":[{"t":"Concepts de base sur les lésions","q":"cours-01-concepts-de-base/quiz.html","f":"cours-01-concepts-de-base/fiche.html"},{"t":"Lésions musculaires","q":"cours-02-lesions-musculaires/quiz.html","f":"cours-02-lesions-musculaires/fiche.html"},{"t":"Lésions tendineuses","q":"cours-03-lesions-tendineuses/quiz.html","f":"cours-03-lesions-tendineuses/fiche.html"},{"t":"Lésions capsulo-ligamentaires","q":"cours-04-lesions-capsulo-ligamentaires/quiz.html","f":"cours-04-lesions-capsulo-ligamentaires/fiche.html"},{"t":"Dysfonctions biomécaniques","q":"cours-05-dysfonctions-biomecaniques/quiz.html","f":"cours-05-dysfonctions-biomecaniques/fiche.html"},{"t":"Dysfonctions du tissu osseux et cartilagineux","q":"cours-06-tissu-osseux-cartilagineux/quiz.html","f":"cours-06-tissu-osseux-cartilagineux/fiche.html"},{"t":"Dysfonctions vertébrales et radiculaires","q":"cours-07-dysfonctions-vertebrales/quiz.html","f":"cours-07-dysfonctions-vertebrales/fiche.html"},{"t":"Dysfonctions rhumatologiques et conditions métaboliques","q":"cours-08-rhumatologie-metabolique/quiz.html","f":"cours-08-rhumatologie-metabolique/fiche.html"},{"t":"Principes de l'exercice en CMS","q":"cours-09-exercice-en-cms/quiz.html","f":"cours-09-exercice-en-cms/fiche.html"}],"questions":[{"q":"Parmi ces structures, laquelle appartient aux tissus contractiles ?","o":["La structure musculo-tendineuse","Le ligament","La capsule articulaire","Le fascia"],"r":0,"e":"Seules les structures musculo-tendineuses sont classées comme contractiles, même si le tendon ne se contracte pas de façon directe.","s":0},{"q":"Quelle est la fonction principale des tissus non contractiles ?","o":["Soutien, stabilité et transmission de force","Produire du mouvement par la contraction","Assurer la conduction nerveuse","Stocker de l'énergie chimique"],"r":0,"e":"Ligaments, capsules, fascias, cartilage et tissu conjonctif assurent soutien, stabilité et transmission de force.","s":0},{"q":"Quelle propriété mécanique du muscle correspond au retour à la longueur d'origine ?","o":["L'élasticité","L'extensibilité","La contractilité","La viscosité"],"r":0,"e":"Extensibilité = s'allonger ; élasticité = revenir à la longueur d'origine ; contractilité = générer une tension ; viscosité = résister à la déformation rapide.","s":0},{"q":"Quelle propriété correspond à la résistance à la déformation rapide ?","o":["La viscosité","L'élasticité","L'extensibilité","La contractilité"],"r":0,"e":"La viscosité est la résistance opposée à une déformation rapide.","s":0},{"q":"Quel est le pourcentage de collagène de type I dans le tendon ?","o":["85 à 95 %","40 à 50 %","20 à 30 %","100 %"],"r":0,"e":"Le tendon est riche en collagène de type I, à hauteur de 85 à 95 %.","s":0},{"q":"Que signifie « comportement viscoélastique » pour le tendon ?","o":["Il subit une déformation dépendante du temps et de la charge","Il se déforme uniquement en fonction de la charge","Il ne se déforme jamais","Il se rompt dès la première contrainte"],"r":0,"e":"Viscoélastique = la déformation dépend à la fois du temps d'application et de l'intensité de la charge.","s":0},{"q":"Quelle cellule est prédominante dans le tissu conjonctif proprement dit ?","o":["Le fibroblaste","L'ostéoclaste","Le chondrocyte","Le myofibroblaste"],"r":0,"e":"Le fibroblaste est la cellule prédominante : il synthétise le collagène et répond aux stimuli mécaniques.","s":0},{"q":"Comment appelle-t-on le fibroblaste mature d'aspect fusiforme ?","o":["Le fibrocyte","Le myofibroblaste","Le mastocyte","L'adipocyte"],"r":0,"e":"Le fibrocyte est le fibroblaste arrivé à maturation.","s":0},{"q":"De quoi est composée la matrice extracellulaire du tissu conjonctif proprement dit ?","o":["De fibres et de substance fondamentale (amorphe)","Uniquement de fibres de collagène","Uniquement de cellules","De calcium et de phosphate"],"r":0,"e":"Fibres (élastiques, de collagène, réticulaires) + substance fondamentale composée d'eau, protéines, glucides et lipides.","s":0},{"q":"Quelle affirmation sur les cross-links est correcte ?","o":["Plus de cross-links = plus de résistance et moins de mobilité","Plus de cross-links = plus de mobilité","Les cross-links n'influencent pas la résistance","Les cross-links diminuent la résistance à la tension"],"r":0,"e":"Le nombre de cross-links détermine la résistance de la structure, au prix de la mobilité.","s":0},{"q":"Que provoque l'immobilisation au niveau du tissu conjonctif ?","o":["Une diminution de la substance amorphe et une augmentation des cross-links","Une augmentation de la substance amorphe et moins de cross-links","Une destruction complète du collagène","Aucune modification structurelle"],"r":0,"e":"L'immobilisation diminue la substance amorphe (++ GAG), ce qui augmente le nombre de cross-links et fait perdre de la mobilité.","s":0},{"q":"Qu'est-ce que le creep (fluage) ?","o":["La déformation progressive du tissu dans le temps sous une force constante","La diminution de la force nécessaire pour maintenir une déformation","La rupture brutale du tissu","Le retour élastique immédiat"],"r":0,"e":"Le creep = capacité du tissu à se déformer dans le temps sous force constante jusqu'à un état d'équilibre.","s":0},{"q":"Qu'est-ce que la stress-relaxation ?","o":["La diminution de la force requise pour maintenir la déformation dans le temps","L'allongement du tissu sous force constante","La perte définitive d'élasticité","L'augmentation de la contrainte au cours du temps"],"r":0,"e":"La relaxation se définit comme la diminution de la force nécessaire pour maintenir une déformation donnée dans le temps.","s":0},{"q":"À partir de quel pourcentage de déformation apparaissent les micro-lésions ?","o":["4 %","1 %","8 %","15 %"],"r":0,"e":"Sur la courbe contrainte/déformation : micro-lésions à partir de 4 %, macro-lésions à partir de 8 %.","s":0},{"q":"À partir de quel pourcentage de déformation apparaissent les macro-lésions ?","o":["8 %","4 %","2 %","20 %"],"r":0,"e":"Les macro-lésions surviennent à partir de 8 % de déformation.","s":0},{"q":"Une lésion produite par une surcharge répétitive est dite :","o":["Microtraumatique","Macrotraumatique","Congénitale","Dégénérative pure"],"r":0,"e":"La lésion microtraumatique résulte d'une surcharge répétitive ou d'un mécanisme incorrect d'utilisation.","s":0},{"q":"Quelle est la caractéristique clinique d'une lésion macrotraumatique ?","o":["Douleur et incapacité immédiates","Installation lente sur plusieurs mois","Absence totale de douleur","Symptômes uniquement nocturnes"],"r":0,"e":"Produit d'un traumatisme aigu, elle cause douleur et incapacité immédiates.","s":0},{"q":"Quels sont les objectifs généraux face à une lésion des tissus mous ?","o":["Contrôler l'inflammation, minimiser les complications et créer les conditions de la réparation","Supprimer totalement l'inflammation dès la première heure","Immobiliser définitivement le segment","Renforcer immédiatement à charge maximale"],"r":0,"e":"Ce sont les trois objectifs généraux énoncés dans le cours.","s":0},{"q":"Dans quel ordre se succèdent les phases de cicatrisation ?","o":["Inflammatoire → réparation → remodelage","Réparation → inflammatoire → remodelage","Remodelage → inflammatoire → réparation","Inflammatoire → remodelage → réparation"],"r":0,"e":"La cascade est toujours : inflammation, puis réparation, puis remodelage.","s":0},{"q":"Quelle phase détermine la forme et la fonction finales du tissu ?","o":["La phase de remodelage","La phase inflammatoire","La phase de réparation","La phase de granulation"],"r":0,"e":"C'est le remodelage (régénération) qui détermine la forme et la fonction finales.","s":0},{"q":"Sur quoi la phase inflammatoire est-elle fondée ?","o":["Sur la vascularisation","Sur l'innervation","Sur la minéralisation","Sur la contraction musculaire"],"r":0,"e":"La réponse inflammatoire est une réponse biologique séquentielle fondée sur la vascularisation.","s":0},{"q":"Quelle liste ne contient que des substances algogènes endogènes ?","o":["Prostaglandines, substance P, sérotonine, bradykinine, histamine","Collagène, élastine, kératine","Ostéocalcine, vitamine D, calcium","Actine, myosine, titine"],"r":0,"e":"Ce sont les substances libérées par les cellules endommagées qui agissent sur les récepteurs de la douleur.","s":0},{"q":"Quels mécanismes expliquent l'œdème en phase inflammatoire ?","o":["La stase et la libération de fluides","La vasoconstriction et la déshydratation","La minéralisation de la matrice","La contraction des myofibroblastes"],"r":0,"e":"L'œdème résulte de la stase circulatoire et de la libération de fluides.","s":0},{"q":"Quel objectif appartient à la phase inflammatoire ?","o":["Maintenir la mobilité et la force des segments non atteints","Reprendre la compétition","Travailler à charge maximale","Normaliser complètement le ROM"],"r":0,"e":"En phase inflammatoire on protège la zone lésée mais on entretient les segments voisins non atteints.","s":0},{"q":"Quelle est l'évolution historique des acronymes de prise en charge aiguë ?","o":["RICE → PRICE → POLICE → PEACE & LOVE","PEACE & LOVE → POLICE → RICE","POLICE → RICE → PRICE","RICE → HARM → POLICE"],"r":0,"e":"C'est l'évolution décrite dans le cours, en référence au BJSM 2019.","s":0},{"q":"Que désigne l'acronyme HARM ?","o":["Heat, Alcool, Running activities, Massage — à éviter en phase aiguë","Les quatre étapes de la réparation","Un protocole de renforcement","Les signes cardinaux de l'inflammation"],"r":0,"e":"HARM regroupe ce qu'il faut éviter en phase aiguë : chaleur, alcool, activités en charge et massage.","s":0},{"q":"Quelles cellules déclenchent la néovascularisation en phase de réparation ?","o":["Les macrophages","Les ostéoclastes","Les mastocytes","Les chondrocytes"],"r":0,"e":"Les macrophages déclenchent le processus de néovascularisation.","s":0},{"q":"Quel est le rôle des myofibroblastes en phase de réparation ?","o":["Générer une force centripète pour diminuer la zone à réparer","Détruire le tissu de granulation","Assurer la minéralisation osseuse","Produire du liquide synovial"],"r":0,"e":"Ils adhèrent à la marge de la lésion et génèrent une force centripète qui contracte la zone lésée.","s":0},{"q":"Comment se caractérise le tissu de granulation ?","o":["État gélatineux avec des fibrilles désorganisées","Tissu lamellaire parfaitement orienté","Tissu cartilagineux minéralisé","Tissu adipeux mature"],"r":0,"e":"Le tissu de granulation est gélatineux, avec des fibrilles désorganisées au niveau de la lésion.","s":0},{"q":"Quel principe s'applique au travail de force en phase de réparation ?","o":["Charges sous-maximales, graduelles, dans le ROM disponible et pain-free","Charges maximales dès le premier jour","Travail exclusivement en amplitude extrême","Vitesse maximale d'exécution"],"r":0,"e":"En réparation : mouvement sélectif, charges sous-maximales graduelles, ROM disponible, pain-free, vitesse lente et contrôlée.","s":0},{"q":"Quels tissus appartiennent au tissu conjonctif spécialisé ?","o":["Le sang","Le tissu osseux","Le tissu cartilagineux","Les ligaments","Le tissu adipeux"],"r":[0,1,2,4],"e":"Le tissu conjonctif spécialisé regroupe le sanguin, l'osseux, le cartilagineux, le lymphatique et l'adipeux. Les ligaments relèvent du tissu conjonctif proprement dit.","s":0},{"q":"Quelles sont les quatre fonctions du tissu conjonctif proprement dit ?","o":["Soutien","Remplissage","Défense","Nutrition","Contraction"],"r":[0,1,2,3],"e":"Soutien, remplissage, défense et nutrition. La contraction est le propre des tissus contractiles.","s":0},{"q":"Que contient la substance fondamentale (ou amorphe) de la matrice extracellulaire ?","o":["Eau, protéines, glucides et lipides","Uniquement des fibres de collagène","Des fibroblastes et des macrophages","Du tropocollagène pur"],"r":0,"e":"La substance amorphe est faite d'eau, de protéines, de glucides et de lipides. Les fibres (collagène, élastiques, réticulaires) en sont distinctes, et les cellules ne font pas partie de la matrice.","s":0},{"q":"Quelles fibres trouve-t-on dans la matrice extracellulaire du tissu conjonctif proprement dit ?","o":["Fibres élastiques","Fibres de collagène","Fibres réticulaires","Fibres musculaires lisses"],"r":[0,1,2],"e":"Élastiques, de collagène et réticulaires. Les fibres musculaires lisses appartiennent au tissu musculaire, pas à la matrice conjonctive.","s":0},{"q":"Le fibroblaste répond aux stimuli mécaniques. Quelle conséquence pratique en découle ?","o":["La mise en charge progressive oriente la qualité du tissu réparé","Le tissu cicatrise identiquement quelle que soit la sollicitation","Il faut immobiliser jusqu'au remodelage complet","Seuls les médicaments modifient la synthèse de collagène"],"r":0,"e":"Parce que le fibroblaste est mécanosensible, la sollicitation graduée pendant la réparation et le remodelage influence directement l'orientation des fibres et la qualité finale du tissu.","s":0},{"q":"Pourquoi le tissu cicatriciel ne reproduit-il pas exactement l'architecture d'origine ?","o":["Les fibroblastes sont des cellules stables, sans capacité de reproduction fidèle de l'architecture initiale","Le collagène de type I est absent de la cicatrice","La néovascularisation empêche toute organisation","Les cross-links ne se forment jamais dans une cicatrice"],"r":0,"e":"Les fibroblastes sont des cellules stables : ils reconstruisent mais n'ont pas toujours la capacité de restituer l'architecture exacte du tissu d'origine, d'où la fibrose.","s":0},{"q":"Quel phénomène de la phase de réparation vise à réduire la surface à réparer ?","o":["La contraction de la zone lésée par les myofibroblastes","La phagocytose","L'épithélialisation","La stress-relaxation"],"r":0,"e":"Les myofibroblastes adhèrent aux marges de la lésion et génèrent une force centripète qui rapproche les berges, diminuant la zone à réparer.","s":0},{"q":"Quel est le rôle de l'épithélialisation en phase de réparation ?","o":["Former une fine couche cellulaire de protection contre les infections et de contention des fluides","Détruire les débris cellulaires","Créer les cross-links définitifs","Déclencher la néovascularisation"],"r":0,"e":"L'épithélialisation est une prolifération cellulaire qui forme une fine couche protectrice : barrière contre l'infection et contention des fluides.","s":0},{"q":"Pendant la néovascularisation, quel élément est décrit comme essentiel ?","o":["L'immobilisation de la zone","La mise en charge maximale","Le massage profond","L'application de chaleur"],"r":0,"e":"La fiche précise que l'immobilisation de la zone est essentielle pendant la néovascularisation ; chaleur et massage font d'ailleurs partie de HARM.","s":0},{"q":"De quoi dépendent les caractéristiques finales du tissu lésé, en phase de remodelage ?","o":["De l'équilibre synthèse/dégradation (turn over)","De l'orientation des fibres","Du tropocollagène","De la solidité des cross-links","De la seule durée d'immobilisation"],"r":[0,1,2,3],"e":"Quatre déterminants : le turn over synthèse/dégradation, l'orientation des fibres, le tropocollagène et des cross-links plus solides.","s":0},{"q":"Quel objectif caractérise spécifiquement la phase de remodelage ?","o":["La réintégration fonctionnelle, professionnelle et sportive en minimisant les récidives","Le contrôle de la réponse inflammatoire","La stabilisation de la situation aiguë","La seule diminution de l'œdème"],"r":0,"e":"Le remodelage vise la réintégration fonctionnelle, professionnelle et sportive, c'est-à-dire la prévention secondaire des récidives.","s":0},{"q":"« Prévention secondaire », dans ce contexte, signifie :","o":["Éviter la récidive chez un patient déjà lésé","Éviter l'apparition d'une première lésion","Dépister une lésion asymptomatique","Limiter les séquelles d'un handicap installé"],"r":0,"e":"La prévention secondaire s'adresse à un patient déjà lésé : l'objectif est d'éviter que la lésion ne se reproduise.","s":0},{"q":"Quels critères autorisent la réintégration après une lésion des tissus mous ?","o":["Absence de douleur et/ou de mécanismes de compensation","Absence d'épanchement articulaire et d'œdème","Mobilité fonctionnelle complète et symétrique","Retour au niveau de performance antérieur dès la première séance"],"r":[0,1,2],"e":"Trois critères : plus de douleur ni de compensation, plus d'épanchement ni d'œdème, et une mobilité fonctionnelle complète et symétrique.","s":0},{"q":"Quels éléments font partie des critères de prévention avant le retour au sport ?","o":["Force musculaire au niveau pré-lésionnel","Ratios agonistes/antagonistes normalisés","Stabilité articulaire normale","Travail pliométrique","Confiance psychologique","Reprise de la compétition dès la disparition de la douleur"],"r":[0,1,2,3,4],"e":"Les cinq sont cités : force pré-lésionnelle, ratios agonistes/antagonistes, stabilité articulaire, pliométrie et confiance psychologique — à quoi s'ajoute le maintien de la condition physique.","s":0},{"q":"Un patient présente une douleur d'installation progressive, sans traumatisme identifiable, apparue après une augmentation de sa charge d'entraînement. De quel type de lésion s'agit-il ?","o":["Microtraumatique","Macrotraumatique","Lésion capsulaire aiguë","Rupture complète"],"r":0,"e":"Surcharge répétitive et installation progressive signent la lésion microtraumatique, par opposition au macrotraumatisme aigu à douleur et incapacité immédiates.","s":0},{"q":"Quelle est la différence entre le creep et la stress-relaxation ?","o":["Le creep se produit sous force constante, la stress-relaxation sous déformation constante","Le creep se produit sous déformation constante, la stress-relaxation sous force constante","Les deux se produisent sous force constante","Le creep est instantané, la stress-relaxation est différée"],"r":0,"e":"Creep : déformation progressive sous une force constante. Stress-relaxation : diminution de la force nécessaire pour maintenir une déformation constante. Les deux caractérisent la viscoélasticité.","s":0},{"q":"Un tissu subit une déformation de 6 %. Que peut-on en attendre ?","o":["Des micro-lésions, le seuil de 4 % étant dépassé mais pas celui de 8 %","Aucune lésion, le seuil de 8 % n'étant pas atteint","Des macro-lésions","Une rupture complète"],"r":0,"e":"Les micro-lésions apparaissent dès 4 % de déformation ; les macro-lésions à partir de 8 %. À 6 % on est donc dans la zone de micro-lésions.","s":0},{"q":"Pourquoi le massage est-il déconseillé en phase inflammatoire aiguë (HARM) ?","o":["Il majore la vascularisation et l'œdème dans une zone déjà hyperperméable","Il détruit les cross-links néoformés","Il empêche la phagocytose","Il provoque une stress-relaxation excessive"],"r":0,"e":"HARM = Heat, Alcohol, Running, Massage. Ces quatre éléments augmentent le débit sanguin et l'œdème alors que la perméabilité vasculaire est déjà accrue.","s":0},{"q":"Quels objectifs sont poursuivis en phase de réparation ?","o":["Diminuer la douleur et l'œdème","Augmenter le ROM, la force et la flexibilité","Rééduquer le système sensori-moteur","Normaliser le ratio force/flexibilité","Obtenir d'emblée des charges maximales"],"r":[0,1,2,3],"e":"La phase de réparation combine antalgie, gain de mobilité/force/flexibilité, rééducation sensori-motrice et normalisation du ratio force/flexibilité. Les charges y restent sous-maximales et graduelles.","s":0},{"q":"Comment doivent être appliquées les résistances en phase de réparation ?","o":["Sous-maximales, graduelles, dans le ROM disponible, sans douleur et à vitesse lente et contrôlée","Maximales dès que la douleur a disparu","En amplitude complète quelle que soit la limitation","À vitesse rapide pour stimuler les fibroblastes"],"r":0,"e":"Le principe est : charges sous-maximales appliquées graduellement, dans le ROM disponible, pain-free, à vitesse lente et contrôlée.","s":0},{"q":"Quelle est l'incidence des lésions musculo-squelettiques parmi tous les traumatismes en médecine du sport ?","o":["10 % à 55 %","1 % à 5 %","60 % à 90 %","Moins de 1 %"],"r":0,"e":"Maffulli et al. (2014) rapportent une incidence de 10 à 55 % de toutes les lésions.","s":1},{"q":"Combien de personnes dans le monde vivent avec des conditions musculo-squelettiques selon l'OMS (2022) ?","o":["Environ 1,71 milliard","Environ 170 millions","Environ 17 millions","Environ 500 millions"],"r":0,"e":"L'OMS estime ce chiffre à approximativement 1,71 milliard de personnes.","s":1},{"q":"Quels sont les trois muscles les plus fréquemment touchés ?","o":["Quadriceps, ischio-jambiers, gastrocnémiens","Deltoïde, trapèze, grand dorsal","Psoas, carré des lombes, diaphragme","Supra-épineux, biceps, triceps"],"r":0,"e":"Le trio classique est quadriceps, ischio-jambiers et gastrocnémiens ; viennent ensuite adducteurs, supra-épineux et longue portion du biceps.","s":1},{"q":"La lacération musculaire relève de quel mécanisme ?","o":["Traumatisme direct","Traumatisme indirect","Fatigue musculaire","Myalgie d'effort"],"r":0,"e":"Ruptures, contusions et lacérations relèvent du traumatisme direct.","s":1},{"q":"La myalgie d'effort relève de quel mécanisme ?","o":["Traumatisme indirect","Traumatisme direct","Contusion","Lacération"],"r":0,"e":"Fatigue musculaire, myalgie d'effort et ruptures musculaires figurent parmi les mécanismes indirects.","s":1},{"q":"Quel est l'objectif de l'évolution des classifications des lésions musculaires ?","o":["Améliorer la capacité pronostique de la lésion","Réduire le coût de l'imagerie","Simplifier le codage administratif","Remplacer l'examen clinique"],"r":0,"e":"Toutes les classifications successives visent à mieux prédire l'évolution et le délai de retour au jeu.","s":1},{"q":"En quelle année a été publié le Consensus de Munich ?","o":["2012","2014","2018","2008"],"r":0,"e":"Munich 2012, BAMIC 2014, MLG-R 2018.","s":1},{"q":"Que signifie BAMIC ?","o":["British Athletic Muscle Injury Classification","Barcelona Muscle Injury Classification","Basic Assessment of Muscle Injury Criteria","British Assessment of Musculoskeletal Injury Care"],"r":0,"e":"BAMIC = British Athletic Muscle Injury Classification (Pollock et al., BJSM 2014).","s":1},{"q":"De quel groupe provient la classification MLG-R ?","o":["Barcelona Innovation Hub","British Athletics","Consensus de Munich","FIFA Medical Network"],"r":0,"e":"La MLG-R (2018) est issue du Barcelona Innovation Hub.","s":1},{"q":"Comment distingue-t-on lésion fonctionnelle et lésion structurelle ?","o":["La fonctionnelle n'est pas visible aux examens complémentaires, la structurelle l'est","La fonctionnelle est toujours plus grave","La structurelle ne provoque jamais de douleur","La distinction repose uniquement sur la durée des symptômes"],"r":0,"e":"Fonctionnelle = sans lésion visible à l'imagerie ; structurelle = avec lésion visible.","s":1},{"q":"Dans quel délai maximal les DOMS peuvent-ils survenir après l'effort ?","o":["Jusqu'à 72 h","Jusqu'à 12 h","Jusqu'à 7 jours","Immédiatement uniquement"],"r":0,"e":"Les DOMS peuvent apparaître jusqu'à 72 h après l'effort.","s":1},{"q":"Quel est le pic de symptomatologie le plus typique des DOMS ?","o":["24 à 48 h après l'effort","2 à 4 h après l'effort","5 à 7 jours après l'effort","Pendant l'effort"],"r":0,"e":"Le pic est variable d'une personne à l'autre mais typiquement situé entre 24 et 48 h.","s":1},{"q":"À quel type de la classification de Munich correspondent les DOMS ?","o":["Type 1b","Type 2a","Type 3a","Type 4"],"r":0,"e":"Les DOMS sont classés comme lésion musculaire de type 1b.","s":1},{"q":"Quel type de contraction prédomine dans la survenue des DOMS ?","o":["Les contractions excentriques","Les contractions isométriques","Les contractions concentriques","Les contractions isocinétiques"],"r":0,"e":"Les DOMS sont plus fréquents avec une prédominance de contractions excentriques, après une pause ou de nouveaux exercices.","s":1},{"q":"Dans les DOMS, la rupture des bandes Z prédomine dans quel type de fibres ?","o":["Les fibres de type II","Les fibres de type I","Les fibres cardiaques","Les fibres lisses"],"r":0,"e":"La rupture des bandes Z prédomine dans les fibres de type II.","s":1},{"q":"Quelle stratégie ne figure PAS parmi les interventions proposées pour les DOMS ?","o":["Renforcement excentrique maximal","Massage","Pressothérapie","Cryothérapie ou bains de contraste"],"r":0,"e":"Les stratégies retenues sont mobilité, flexibilité, massage, pressothérapie, cryothérapie et bains de contraste.","s":1},{"q":"Quelle est l'évolution habituelle des DOMS ?","o":["Bénigne","Vers la chronicité dans la majorité des cas","Vers la rupture structurelle","Vers une myosite ossifiante"],"r":0,"e":"Le cours précise que l'évolution est bénigne.","s":1},{"q":"Dans une lésion musculaire « mineure », quel est l'état du ROM ?","o":["Complet","Diminué de moitié","Totalement aboli","Augmenté"],"r":0,"e":"La lésion mineure touche quelques fibres : douleur au mouvement actif mais ROM complet.","s":1},{"q":"Quel signe caractérise une lésion de plus de 50 % des fibres ?","o":["Perte totale de ROM et incapacité à la contraction","ROM complet et douleur légère","Absence de déformation","Douleur uniquement nocturne"],"r":0,"e":"Au-delà de 50 % : douleur intense au moment de la lésion, perte totale de ROM, incapacité à la contraction, déformation marquée.","s":1},{"q":"Quel mécanisme est typiquement associé aux lésions du quadriceps ?","o":["La décélération","L'accélération","L'immobilisation prolongée","La contraction isométrique lente"],"r":0,"e":"Accélération surtout pour les ischio-jambiers, décélération surtout pour le quadriceps.","s":1},{"q":"Quel mécanisme est typiquement associé aux lésions des ischio-jambiers ?","o":["L'accélération","La décélération","La flexion passive lente","La contraction excentrique du quadriceps"],"r":0,"e":"L'accélération est le mécanisme prédominant pour les ischio-jambiers.","s":1},{"q":"Quelle population est typiquement touchée par les lésions des jumeaux et du soléaire ?","o":["Les athlètes d'âge moyen et récréatifs","Les enfants de moins de 10 ans","Les personnes alitées","Les nageurs exclusivement"],"r":0,"e":"Ces lésions sont prévalentes chez les athlètes d'« âge moyen » et récréatifs, lors d'activités balistiques en décélération.","s":1},{"q":"Quelle insertion figure parmi les avulsions myotendineuses les plus fréquentes ?","o":["L'insertion proximale du droit fémoral","L'insertion du deltoïde","L'insertion distale du trapèze","L'insertion du muscle temporal"],"r":0,"e":"Les plus fréquentes : insertion proximale du droit fémoral, proximale des IJ, long adducteur, distale du semi-tendineux.","s":1},{"q":"Quel objectif relève de la phase de remodelage dans les lésions musculaires ?","o":["Prévenir la kinésiophobie et préparer le geste fonctionnel/sportif","Résorber l'œdème initial","Prévenir l'aggravation de la lésion","Déclencher la néovascularisation"],"r":0,"e":"Le remodelage vise la normalisation de la fonction, la préparation au geste sportif et la prévention de la récidive et de la kinésiophobie.","s":1},{"q":"Quand la chirurgie est-elle indiquée dans les lésions musculaires ?","o":["En cas de lésion totale ou d'avulsion myo-tendineuse","Dès le grade « mineur »","Systématiquement chez le sportif","En cas de DOMS persistants"],"r":0,"e":"Le traitement conservateur est le plus fréquent ; la chirurgie est réservée aux lésions totales et aux avulsions.","s":1},{"q":"Quelle stratégie post-opératoire est recommandée après suture musculaire ?","o":["Mobilisation précoce et contractions isométriques","Immobilisation stricte pendant 3 mois","Charge maximale immédiate","Massage profond de la cicatrice dès J1"],"r":0,"e":"On cherche à inverser les conséquences de l'immobilisation : PEACE & LOVE, mobilisation précoce, isométrie, charge progressive.","s":1},{"q":"Quelle est la caractéristique d'une contusion musculaire ?","o":["Traumatisme direct sans discontinuité structurelle","Rupture complète des fibres","Lésion exclusivement indirecte","Absence totale d'épanchement"],"r":0,"e":"La contusion résulte d'un traumatisme direct, sans discontinuité structurelle, avec un possible épanchement associé.","s":1},{"q":"Que faut-il éviter en présence d'un hématome intramusculaire ?","o":["La compression et le massage","La cryothérapie","Le repos relatif","L'élévation du membre"],"r":0,"e":"Compression et massage sont formellement contre-indiqués en présence d'un hématome intramusculaire.","s":1},{"q":"À quels muscles la myosite ossifiante est-elle le plus souvent associée ?","o":["Quadriceps et biceps","Deltoïde et trapèze","Psoas et iliaque","Soléaire et tibial antérieur"],"r":0,"e":"La myosite ossifiante est plus fréquente au quadriceps et au biceps, après chocs cycliques et contusions.","s":1},{"q":"Quel est le traitement du syndrome des loges aigu ?","o":["La fasciotomie en urgence","La cryothérapie seule","Les étirements de la loge","La modification de l'activité"],"r":0,"e":"La forme aiguë est une urgence chirurgicale : fasciotomie. Le traitement conservateur ne concerne que la forme chronique.","s":1},{"q":"Quels muscles figurent parmi les « autres localisations » touchées, en dehors du trio le plus fréquent ?","o":["Adducteurs de hanche","Supra-épineux","Longue portion du biceps","Gastrocnémiens"],"r":[0,1,2],"e":"Après quadriceps, ischio-jambiers et gastrocnémiens viennent les adducteurs de hanche, le supra-épineux et la longue portion du biceps.","s":1},{"q":"Quelles lésions relèvent d'un traumatisme direct ?","o":["Ruptures musculaires","Contusions","Lacérations","Myalgie d'effort"],"r":[0,1,2],"e":"Le traumatisme direct produit ruptures, contusions et lacérations. La myalgie d'effort et la fatigue musculaire relèvent du mécanisme indirect.","s":1},{"q":"Les ruptures musculaires apparaissent dans les deux colonnes de mécanismes. Qu'est-ce que cela signifie ?","o":["Une rupture peut survenir aussi bien par choc direct que par sollicitation indirecte","La classification est erronée","Seul le mécanisme direct produit de vraies ruptures","Les ruptures indirectes sont toujours partielles"],"r":0,"e":"Les ruptures musculaires figurent dans les deux colonnes : elles peuvent résulter d'un choc direct comme d'une sollicitation indirecte excessive.","s":1},{"q":"Dans quelles circonstances les DOMS sont-ils plus fréquents ?","o":["Après une pause prolongée","À l'introduction de nouveaux exercices","Avec une prédominance de contractions excentriques","Lors d'un travail isométrique de faible intensité"],"r":[0,1,2],"e":"Reprise après pause, nouveaux exercices et travail excentrique sont les trois situations favorisantes.","s":1},{"q":"Quels signes et symptômes accompagnent les DOMS ?","o":["Douleurs musculaires post-exercice","Raideur","Œdème","Perte de force","Déformation visible du corps musculaire"],"r":[0,1,2,3],"e":"Douleur, raideur, œdème et perte de force. Une déformation visible évoquerait une lésion structurelle, pas des DOMS.","s":1},{"q":"Quels mécanismes physiopathologiques sont impliqués dans les DOMS ?","o":["Rupture des bandes Z","Accumulation de lactate","Altérations enzymatiques","Mécanismes inflammatoires","Rupture complète de la jonction myo-tendineuse"],"r":[0,1,2,3],"e":"Les DOMS sont multifactoriels : rupture des bandes Z (fibres de type II), lactate, altérations enzymatiques et inflammation.","s":1},{"q":"Quelles interventions kinésithérapiques sont proposées face aux DOMS ?","o":["Mobilité et flexibilité","Massage","Pressothérapie","Cryothérapie et/ou bains de contraste","Renforcement excentrique maximal immédiat"],"r":[0,1,2,3],"e":"Mobilité, flexibilité, massage, pressothérapie, cryothérapie ou bains de contraste. Réintroduire immédiatement de l'excentrique maximal aggraverait les symptômes.","s":1},{"q":"Qu'est-ce qui définit une lésion musculaire structurelle ?","o":["Une perte de continuité de la fibre musculaire, éventuellement à la jonction myo-tendineuse","Une douleur retardée sans anomalie à l'imagerie","Une simple accumulation de lactate","Un œdème isolé sans douleur"],"r":0,"e":"La lésion structurelle est définie par la perte de continuité de la fibre, avec possible discontinuité de la jonction myo-tendineuse — et elle est visible à l'imagerie.","s":1},{"q":"Un patient a une douleur au mouvement actif mais un ROM complet, avec quelques fibres discontinues. Quel est le degré de gravité ?","o":["Lésion « mineure »","Lésion < 50 %","Lésion > 50 %","Avulsion myo-tendineuse"],"r":0,"e":"Perte de continuité de quelques fibres, douleur au mouvement actif et ROM complet définissent la lésion mineure.","s":1},{"q":"Quels signes accompagnent une lésion de moins de 50 % des fibres ?","o":["Douleur à la contraction active","Perte de ROM","Déformation","Hémorragie","Incapacité totale de contraction"],"r":[0,1,2,3],"e":"Douleur à la contraction active, perte de ROM, déformation et hémorragie. L'incapacité totale de contraction signe plutôt une lésion > 50 %.","s":1},{"q":"Quel mécanisme est typique des lésions des jumeaux et du soléaire ?","o":["Activités balistiques en décélération, avec sensation d'avoir été « atteint par quelque chose »","Traumatisme direct en compression","Étirement lent et progressif","Contraction isométrique prolongée"],"r":0,"e":"Basket, football, course, sauts, en décélération ; le patient croit souvent avoir reçu un coup ou un projectile.","s":1},{"q":"Quelles insertions figurent parmi les avulsions myo-tendineuses les plus fréquentes ?","o":["Proximale du droit fémoral","Proximale des ischio-jambiers","Long adducteur","Distale du semi-tendineux","Distale du gastrocnémien médial"],"r":[0,1,2,3],"e":"Quatre insertions citées : proximale du droit fémoral, proximale des IJ, long adducteur et distale du semi-tendineux.","s":1},{"q":"Quels sont les objectifs de la phase inflammatoire dans une lésion musculaire ?","o":["Prévenir l'aggravation de la lésion","Favoriser vascularisation, résorption de l'œdème et alignement des fibres","Prévenir les dysfonctions du timing d'activation musculaire et l'atrophie","Préparer immédiatement le geste sportif"],"r":[0,1,2],"e":"Prévenir l'aggravation, créer un meilleur contexte de réparation et prévenir les dysfonctions d'activation et l'atrophie. La préparation au geste sportif relève du remodelage.","s":1},{"q":"Quel objectif appartient à la phase de réparation dans une lésion musculaire ?","o":["Améliorer le contrôle neuromusculaire et la force, en préparant l'objectif fonctionnel","Prévenir la kinésiophobie et la récidive","Prévenir l'aggravation de la lésion","Réaliser une fasciotomie"],"r":0,"e":"La réparation vise l'alignement des fibres, la qualité de contraction et de mouvement, le contrôle neuromusculaire et la force, en préparation de l'objectif fonctionnel.","s":1},{"q":"Pourquoi la prévention de la kinésiophobie figure-t-elle parmi les objectifs du remodelage ?","o":["Parce que l'appréhension du mouvement favorise les compensations et la récidive","Parce qu'elle accélère la formation de collagène","Parce qu'elle remplace le renforcement musculaire","Parce qu'elle est un critère d'imagerie"],"r":0,"e":"La phase de remodelage vise la normalisation de la fonction : éduquer à la qualité du mouvement et lever l'appréhension limite les compensations et donc les récidives.","s":1},{"q":"Quelles stratégies post-opératoires sont recommandées après chirurgie musculaire ?","o":["Inverser les conséquences de l'immobilisation prolongée","PEACE & LOVE","Mobilisation précoce","Contractions isométriques et activation musculaire","Immobilisation stricte jusqu'à cicatrisation complète"],"r":[0,1,2,3],"e":"Lutter contre les effets de l'immobilisation, PEACE & LOVE, mobilisation précoce, isométrie/activation, puis introduction progressive de la charge.","s":1},{"q":"Que faut-il éviter lors de l'évaluation d'une contusion musculaire ?","o":["La contraction et l'étirement maximaux","Toute contraction active","La palpation","L'interrogatoire sur le mécanisme"],"r":0,"e":"On vérifie la fonction active mais on évite la contraction et l'étirement maximaux, qui risquent d'aggraver la lésion.","s":1},{"q":"Quel est le mécanisme de la myosite ossifiante ?","o":["Des chocs cycliques et contusions entraînent des dépôts de calcium entre les fibres et un éperon issu de l'os sous-jacent","Une infection bactérienne du corps musculaire","Une dégénérescence du collagène de type I","Une compression nerveuse chronique"],"r":0,"e":"Chocs cycliques et contusions répétés → accumulation de petits dépôts calciques entre les fibres, avec formation d'un éperon à partir de l'os sous-jacent.","s":1},{"q":"Comment détecte-t-on une myosite ossifiante ?","o":["Par radiographie et/ou échographie de bonne définition","Par un bilan sanguin isolé","Par un test musculaire manuel","Par l'électromyographie seule"],"r":0,"e":"Radiographie et/ou échographie de bonne définition permettent de visualiser les dépôts calciques.","s":1},{"q":"Quelle est la prise en charge du syndrome des loges chronique ?","o":["Conservatrice d'abord : modification de l'activité, cryothérapie, étirements de la loge ; fasciotomie si échec","Fasciotomie en urgence systématique","Immobilisation plâtrée de six semaines","Abstention thérapeutique"],"r":0,"e":"La forme chronique se traite d'abord de façon conservatrice ; la chirurgie n'intervient qu'en cas d'échec. C'est la forme aiguë qui impose la fasciotomie en urgence.","s":1},{"q":"Quelle affirmation décrit correctement la vascularisation du tendon ?","o":["Le tendon est peu vascularisé et le pronostic dépend de la zone lésée","Le tendon est richement vascularisé sur toute sa longueur","Le tendon n'a aucune vascularisation","La vascularisation est identique dans les trois tiers"],"r":0,"e":"Le tendon est peu vascularisé ; le pronostic de récupération est très influencé par la zone de la lésion.","s":2},{"q":"D'où proviennent les vaisseaux du premier tiers du tendon ?","o":["Du périmysium","Du paratendon","De la synoviale","De l'os"],"r":0,"e":"Dans le 1/3, les vaisseaux viennent du périmysium et pénètrent la structure tendineuse.","s":2},{"q":"Quel tissu explique l'absence de connexion directe entre les vaisseaux à la jonction tendon-os ?","o":["Le tissu fibrocartilagineux","Le tissu adipeux","Le tissu synovial","Le périoste"],"r":0,"e":"L'abondance et la désorganisation du tissu fibrocartilagineux empêchent les vaisseaux de se connecter directement entre eux.","s":2},{"q":"Quelle est la définition de la tendinite ?","o":["Inflammation aiguë et primaire du paratendon","Dégénérescence du tendon sans inflammation","Rupture complète du tendon","Calcification du corps musculaire"],"r":0,"e":"La tendinite est une inflammation aiguë et primaire du paratendon, avec ou sans altérations tissulaires.","s":2},{"q":"Quelle est la caractéristique histologique de la tendinose ?","o":["Altérations dégénératives sans signes inflammatoires","Infiltrat inflammatoire massif","Dépôts calciques constants","Néovascularisation inflammatoire aiguë"],"r":0,"e":"La tendinose correspond à des altérations dégénératives sans signes cliniques ni histologiques de réponse inflammatoire.","s":2},{"q":"Quelle conséquence la tendinose chronique a-t-elle sur le tendon ?","o":["Perte de la structure normale du collagène et prédisposition aux ruptures","Renforcement du collagène","Augmentation de la cellularité","Guérison spontanée systématique"],"r":0,"e":"Dans la chronicité : perte de la structure normale du collagène, perte de cellularité, prédisposition aux ruptures.","s":2},{"q":"À quel moment la tendinopathie est-elle la lésion la plus commune ?","o":["En pré-saison et au retour après une pause","En milieu de saison compétitive","Uniquement hors période sportive","Pendant les phases d'immobilisation"],"r":0,"e":"C'est explicitement la lésion la plus commune en pré-saison et/ou au retour après une pause.","s":2},{"q":"Qu'est-ce que la crépitation dans la tendinopathie ?","o":["Des adhérences du paratendon aux structures environnantes lors du glissement","Un dépôt calcique audible","Une rupture partielle des fibres","Un épanchement articulaire"],"r":0,"e":"La crépitation résulte des produits chimiques de l'inflammation accumulés, qui créent des adhérences du paratendon.","s":2},{"q":"Sur quelle structure osseuse s'insèrent les tendons de la coiffe des rotateurs ?","o":["Le trochiter, sous le bord externe de l'acromion","Le trochin, sous la clavicule","Le processus coracoïde","L'épine de la scapula"],"r":0,"e":"Les tendons de la coiffe s'insèrent sur le trochiter, immédiatement sous le bord externe de l'acromion.","s":2},{"q":"Quel type morphologique d'acromion augmente le risque de tendinopathie de la coiffe ?","o":["Le type III","Le type I","Le type 0","Aucun, la morphologie n'intervient pas"],"r":0,"e":"La morphologie de type III favorise le pincement des tendons.","s":2},{"q":"Quel est l'arc douloureux caractéristique de la tendinopathie de la coiffe ?","o":["60° à 120° d'abduction","0° à 30° d'abduction","120° à 180° d'abduction","Il n'y a pas d'arc douloureux"],"r":0,"e":"L'arc douloureux typique se situe entre 60° et 120° d'abduction.","s":2},{"q":"Quel tendon est le plus souvent touché par la tendinopathie calcifiante de la coiffe ?","o":["Le supra-épineux","Le petit rond","Le sous-scapulaire","Le grand rond"],"r":0,"e":"Le dépôt de calcium se fait le plus fréquemment dans le tendon du supra-épineux.","s":2},{"q":"Quelle est la localisation de la douleur dans la tendinopathie calcifiante de l'épaule ?","o":["Face antéro-externe de l'épaule","Face postérieure de l'omoplate","Région cervicale basse","Face interne du bras uniquement"],"r":0,"e":"Douleur très intense de la face antéro-externe, nocturne, avec impotence fonctionnelle marquée.","s":2},{"q":"Dans l'épicondylite, quels mouvements résistés sont douloureux ?","o":["Extension et supination","Flexion et pronation","Abduction et rotation externe","Adduction et rotation interne"],"r":0,"e":"L'épicondylite touche les extenseurs : douleur en extension et supination résistées.","s":2},{"q":"Dans l'épitrochléite, quels mouvements résistés sont douloureux ?","o":["Flexion et pronation","Extension et supination","Abduction et rotation interne","Inclinaison latérale du poignet uniquement"],"r":0,"e":"L'épitrochléite touche les fléchisseurs : douleur en flexion et pronation résistées.","s":2},{"q":"Où se situe la douleur de l'épitrochléite ?","o":["À la face interne du coude et de l'avant-bras","À la face externe du coude","À la face postérieure du bras","À l'épaule"],"r":0,"e":"L'épitrochlée est médiale : douleur à la face interne du coude et de l'avant-bras.","s":2},{"q":"Quelle population est classiquement associée à l'épitrochléite ?","o":["Les golfeurs et les couturières","Les joueurs de tennis et les peintres","Les nageurs","Les coureurs de fond"],"r":0,"e":"Épitrochléite : golfeurs, femmes au foyer, couturières, travail sur ordinateur. Épicondylite : tennis, peintres.","s":2},{"q":"Quelle activité déclenche typiquement la douleur de la tendinopathie rotulienne ?","o":["Les sauts, la course, l'accroupissement et les escaliers","Le décubitus dorsal prolongé","La flexion cervicale","La préhension"],"r":0,"e":"Douleur après sauts, course, accroupissement, montée et descente d'escaliers et position assise.","s":2},{"q":"Quel facteur de risque de la tendinopathie rotulienne est intrinsèque ?","o":["L'angle Q","Le type de chaussures","La qualité du sol","Le volume d'entraînement"],"r":0,"e":"Intrinsèques : âge, genre, angle Q, varus et valgus. Extrinsèques : entraînement, chaussures, sol.","s":2},{"q":"Quelle est la localisation la plus commune de la tendinopathie d'Achille ?","o":["Le tiers moyen et l'insertion","Le tiers proximal uniquement","La jonction myo-tendineuse haute","Le corps du gastrocnémien"],"r":0,"e":"Le début est graduel, plus commun au tiers moyen et à l'insertion.","s":2},{"q":"Quel symptôme est typique de la tendinopathie d'Achille ?","o":["Une raideur matinale qui s'améliore avec le mouvement","Une douleur qui n'apparaît qu'au repos complet","Une paresthésie plantaire nocturne","Un blocage articulaire brutal"],"r":0,"e":"Sensation de raideur matinale s'améliorant avec le mouvement, aggravée par la course en pente.","s":2},{"q":"Quel signe appartient à la phase chronique de la tendinopathie d'Achille ?","o":["Crépitation et raccourcissements adaptatifs de la chaîne postérieure","Tendon chaud et épaissi","Rougeur cutanée intense","Épanchement articulaire"],"r":0,"e":"Phase aiguë : tendon chaud, douloureux, épaissi. Phase chronique : crépitation et raccourcissements adaptatifs.","s":2},{"q":"Quelle maladie métabolique constitue un facteur de risque intrinsèque de tendinopathie ?","o":["Le diabète","La bronchite chronique","La migraine","L'anémie ferriprive"],"r":0,"e":"Les maladies métaboliques citées sont le diabète, l'obésité et l'HTA.","s":2},{"q":"Quel est l'effet principal des exercices excentriques sur le tendon ?","o":["Favoriser la synthèse de collagène et la phase de remodelage","Provoquer une inflammation aiguë","Diminuer le flux sanguin local","Rompre les cross-links"],"r":0,"e":"L'excentrique favorise la synthèse de collagène, augmente le flux sanguin, diminue la douleur et favorise le remodelage.","s":2},{"q":"Pour quelles localisations les exercices isométriques à charges légères à modérées sont-ils particulièrement associés à l'amélioration de la douleur ?","o":["Coiffe des rotateurs et épicondylite","Tendon d'Achille et fascia plantaire","Tendon rotulien uniquement","Ténosynovite de De Quervain"],"r":0,"e":"Le cours cite une relation entre amélioration de la douleur et isométrique surtout pour la coiffe des rotateurs et l'épicondylite.","s":2},{"q":"Quel est le niveau de preuve du massage transverse profond (MTP) dans la tendinopathie d'Achille ?","o":["Sans preuve scientifique","Preuve de haut niveau","Traitement de première intention","Supérieur à l'exercice"],"r":0,"e":"Les preuves sont très faibles par rapport aux autres techniques, et absentes dans la tendinopathie d'Achille.","s":2},{"q":"Sur quelle durée la pharmacothérapie est-elle efficace sur la douleur tendineuse ?","o":["7 à 14 jours (court terme)","3 à 6 mois","Indéfiniment","Elle n'a aucun effet"],"r":0,"e":"Efficacité dans la diminution de la douleur à court terme (7-14 jours), surtout à l'épaule.","s":2},{"q":"Quels tendons sont concernés par la ténosynovite de De Quervain ?","o":["Long abducteur et court extenseur du pouce","Fléchisseur ulnaire et radial du carpe","Extenseur commun des doigts","Long palmaire et fléchisseur superficiel"],"r":0,"e":"Il s'agit d'une sténose des gaines du long abducteur et du court extenseur du pouce, au niveau de la styloïde radiale.","s":2},{"q":"À quelle période du post-partum la ténosynovite de De Quervain apparaît-elle fréquemment ?","o":["De la 4ᵉ à la 6ᵉ semaine après l'accouchement","Dans les 24 premières heures","Après un an","Jamais en post-partum"],"r":0,"e":"Elle apparaît souvent de la 4ᵉ à la 6ᵉ semaine, probablement du fait d'altérations hormonales ou d'une rétention de liquides.","s":2},{"q":"Quels mouvements résistés sont douloureux dans la ténosynovite de la longue portion du biceps ?","o":["Flexion de l'épaule et supination","Extension de l'épaule et pronation","Abduction et rotation interne","Adduction horizontale"],"r":0,"e":"Douleur intense aux mouvements résistés de flexion de l'épaule et de supination, avec douleur à la palpation de la gouttière bicipitale.","s":2},{"q":"Quelles sont les fonctions principales du tendon ?","o":["Union os–muscle","Transmission et absorption des forces","Stabilité articulaire","Production active de la contraction"],"r":[0,1,2],"e":"Le tendon unit l'os au muscle, transmet et absorbe les forces et participe à la stabilité articulaire. Il ne se contracte pas lui-même.","s":2},{"q":"Quelles insertions le tendon présente-t-il ?","o":["Insertion ténopériostée","Insertion myotendineuse","Insertion capsulo-ligamentaire","Insertion synoviale"],"r":[0,1],"e":"Le tendon présente une insertion ténopériostée (côté os) et une insertion myotendineuse (côté muscle).","s":2},{"q":"Quel tiers du tendon est le mieux vascularisé ?","o":["Le tiers moyen, irrigué par le paratendon et la structure synoviale dans les zones de friction","Le tiers proximal","Le tiers d'insertion osseuse","Les trois tiers sont équivalents"],"r":0,"e":"Dans les zones soumises à friction, le tiers moyen reçoit une irrigation du paratendon et de la structure synoviale : c'est la zone la mieux vascularisée.","s":2},{"q":"Pourquoi la zone de la lésion influence-t-elle fortement le pronostic tendineux ?","o":["Parce que le tendon est peu vascularisé et que l'irrigation varie beaucoup d'un tiers à l'autre","Parce que le collagène est absent aux extrémités","Parce que seule l'insertion contient des cellules","Parce que la douleur est plus vive en distal"],"r":0,"e":"Le tendon est globalement peu vascularisé et chaque tiers a une source d'irrigation différente : une lésion en zone mal vascularisée cicatrise moins bien.","s":2},{"q":"Quelles affirmations distinguent correctement tendinite et tendinose ?","o":["La tendinite comporte une inflammation, la tendinose non","La tendinose est tendanciellement asymptomatique","La tendinose prédispose aux ruptures","La tendinite touche primitivement le paratendon","La tendinose s'accompagne d'une inflammation histologique"],"r":[0,1,2,3],"e":"Tendinite : inflammation aiguë et primaire du paratendon, symptomatique. Tendinose : dégénérescence sans inflammation ni clinique ni histologique, souvent asymptomatique, qui prédispose aux ruptures.","s":2},{"q":"Quelles altérations caractérisent la chronicité de la tendinose ?","o":["Perte de la structure normale du collagène","Perte de cellularité","Infiltrat inflammatoire massif","Néovascularisation inflammatoire aiguë"],"r":[0,1],"e":"La tendinose chronique associe perte de la structure normale du collagène et perte de cellularité, sans réponse inflammatoire.","s":2},{"q":"Quels éléments composent le tableau clinique général d'une tendinopathie ?","o":["Douleur au mouvement","Œdème et fibrose","Crépitation","Altérations du schéma de recrutement moteur","Fièvre"],"r":[0,1,2,3],"e":"Douleur au mouvement, œdème et fibrose, crépitation par adhérences du paratendon, et altération du recrutement moteur.","s":2},{"q":"Quelle disposition anatomique favorise le conflit dans la tendinopathie de la coiffe ?","o":["L'insertion sur le trochiter, juste sous le bord externe de l'acromion","L'insertion sur le trochin, au-dessus de l'acromion","Le passage dans la gouttière bicipitale","L'insertion sur la glène"],"r":0,"e":"Les tendons s'insèrent sur le trochiter immédiatement sous le bord externe de l'acromion, ce qui favorise le pincement contre la face inférieure de l'acromion et le ligament coraco-acromial.","s":2},{"q":"Quelles pathologies sont classiquement associées à la tendinopathie de la coiffe ?","o":["Syndrome de conflit sous-acromial","Bursite sous-acromiale","Tendinopathie calcifiante","Ténosynovite de De Quervain"],"r":[0,1,2],"e":"Conflit sous-acromial, bursite sous-acromiale et tendinopathie calcifiante. De Quervain concerne le poignet.","s":2},{"q":"Quels signes caractérisent la tendinopathie calcifiante de l'épaule ?","o":["Douleur nocturne avec troubles du sommeil","Signes inflammatoires marqués","Impotence fonctionnelle marquée, tout mouvement étant douloureux","Douleur strictement limitée à l'arc de 60° à 120°"],"r":[0,1,2],"e":"La forme calcifiante est très bruyante : douleur nocturne, inflammation marquée et impotence majeure — tout mouvement fait mal, à la différence de l'arc douloureux isolé.","s":2},{"q":"Un patient a mal à la face externe du coude, avec douleur au levage de charges et à la poignée de main. Quel diagnostic évoquez-vous ?","o":["Épicondylite","Épitrochléite","Ténosynovite de De Quervain","Tendinopathie bicipitale"],"r":0,"e":"Face externe, douleur au levage, au transport de charges, aux poignées de main et à la préhension : c'est l'épicondylite, confirmée par l'extension et la supination résistées.","s":2},{"q":"Où palpe-t-on l'insertion douloureuse dans l'épicondylite ?","o":["À l'insertion des tendons extenseurs, juste sous l'épicondyle","À l'insertion des fléchisseurs, sous l'épitrochlée","Sur la gouttière bicipitale","Sur la styloïde radiale"],"r":0,"e":"Épicondylite = tendons extenseurs, palpés juste sous l'épicondyle, sur la face externe.","s":2},{"q":"Quelles activités déclenchent typiquement la douleur d'une tendinopathie rotulienne ?","o":["Les sauts","La course","L'accroupissement","La montée et la descente d'escaliers","La position assise prolongée","La position allongée prolongée"],"r":[0,1,2,3,4],"e":"Toutes ces situations sont citées : sauts, course, accroupissement, escaliers et position assise.","s":2},{"q":"Quels facteurs extrinsèques favorisent la tendinopathie rotulienne ?","o":["Type, volume et qualité d'entraînement","Chaussures","Sol","Angle Q"],"r":[0,1,2],"e":"Entraînement, chaussures et sol sont extrinsèques. L'angle Q, comme l'âge, le genre, le varus et le valgus, est intrinsèque.","s":2},{"q":"Comment évolue la raideur matinale dans la tendinopathie d'Achille ?","o":["Elle s'améliore avec le mouvement","Elle s'aggrave avec le mouvement","Elle est constante toute la journée","Elle n'existe pas dans cette pathologie"],"r":0,"e":"Douleur localisée et raideur matinale qui s'améliore avec le mouvement : c'est un signe caractéristique. La douleur s'aggrave en revanche à la course en pente.","s":2},{"q":"Quels facteurs extrinsèques favorisent la tendinopathie d'Achille ?","o":["Surcharge","Geste technique sous-optimal","Changements brusques d'entraînement","Chaussures","Lésions antérieures","Génétique"],"r":[0,1,2,3,4],"e":"Surcharge, technique, changements d'entraînement, chaussures et antécédents lésionnels. La génétique, les altérations biomécaniques et les maladies métaboliques sont intrinsèques.","s":2},{"q":"Quels sont les deux piliers de l'intervention kinésithérapique dans la tendinopathie ?","o":["La gestion du mouvement et de la charge","L'exercice","L'immobilisation prolongée","La chirurgie de première intention"],"r":[0,1],"e":"Modification de l'activité et rééducation du schéma de mouvement d'une part, exercice (excentrique, concentrique contrôlé, isométrique) d'autre part.","s":2},{"q":"Quels moyens d'électrothérapie sont cités dans la tendinopathie ?","o":["LASER","Ultrasons","Ondes de choc","Électrostimulation fonctionnelle"],"r":[0,1,2],"e":"LASER, ultrasons et ondes de choc sont les trois moyens cités.","s":2},{"q":"Dans quelle localisation la pharmacothérapie est-elle la plus efficace sur la douleur tendineuse ?","o":["L'épaule","L'épicondyle","Le tendon d'Achille","Le tendon rotulien"],"r":0,"e":"La pharmacothérapie soulage à court terme (7 à 14 jours) et se montre plus efficace dans les tendinopathies de l'épaule que dans l'épicondylite ou la tendinopathie d'Achille.","s":2},{"q":"Qu'est-ce qui définit le doigt à ressaut (ténosynovite nodulaire) ?","o":["Un blocage au niveau de l'interphalangienne proximale lors du passage de la flexion à l'extension","Une sténose des gaines du pouce à la styloïde radiale","Une inflammation de la gouttière bicipitale","Une rupture de la plaque palmaire"],"r":0,"e":"Le doigt à ressaut se manifeste par un blocage, douloureux ou non, à l'interphalangienne proximale quand le doigt passe de la flexion à l'extension.","s":2},{"q":"Quelles sont les deux fonctions principales de la capsule et du ligament ?","o":["Nutrition (lubrification) de l'articulation et stabilité articulaire","Production de mouvement et absorption des chocs","Conduction nerveuse et vascularisation","Hématopoïèse et minéralisation"],"r":0,"e":"Le cours retient la nutrition/lubrification de l'articulation et la stabilité articulaire.","s":3},{"q":"Quel grade de lésion ligamentaire ne comporte PAS d'instabilité mécanique ?","o":["Le grade I","Le grade II","Le grade III","Aucun"],"r":0,"e":"Le grade I correspond à un étirement de certaines fibres avec douleur et œdème localisés, sans instabilité mécanique.","s":3},{"q":"Que caractérise une lésion ligamentaire de grade II ?","o":["Rupture partielle avec instabilité modérée","Rupture complète avec impotence totale","Simple étirement sans perte fonctionnelle","Absence d'œdème"],"r":0,"e":"Le grade II implique un traumatisme plus violent, une rupture partielle, une perte fonctionnelle partielle et une instabilité modérée.","s":3},{"q":"Quel est le mécanisme le plus fréquent de l'entorse de la tibio-tarsienne ?","o":["Inversion + flexion plantaire","Éversion + flexion dorsale","Rotation externe pure","Compression axiale"],"r":0,"e":"Inversion associée à la flexion plantaire est le mécanisme le plus fréquent.","s":3},{"q":"Quel test oriente vers une lésion de la syndesmose ?","o":["Le squeeze test","Le test de Lachman","Le test de Neer","Le signe du flot"],"r":0,"e":"Lésion de syndesmose : traumatisme à haute vitesse, douleur très intense, squeeze test positif.","s":3},{"q":"Quelle stratégie est particulièrement soulignée dans la prise en charge de l'entorse de cheville ?","o":["La rééducation sensori-motrice (RSM +++)","L'immobilisation plâtrée systématique de 6 semaines","Le massage profond immédiat","Le repos strict au lit"],"r":0,"e":"PEACE & LOVE, immobilisation sélective, force musculaire, RSM +++ et pliométrie.","s":3},{"q":"Quelle est la fonction du ligament croisé antérieur ?","o":["Contrôler l'antériorisation du tibia par rapport au fémur","Contrôler la postériorisation du tibia","Assurer la stabilité latérale du genou","Transmettre les charges compressives"],"r":0,"e":"Le LCA contrôle l'antériorisation du tibia et stabilise l'articulation fémoro-tibiale.","s":3},{"q":"Quel mécanisme est typique de la lésion du LCA ?","o":["Changement brusque de direction avec fixation du membre inférieur (pivot)","Compression axiale lente","Étirement passif prolongé","Contraction isométrique du quadriceps"],"r":0,"e":"Mécanisme traumatique en pivot ; un mécanisme neurocognitif lié aux tâches multiples est également évoqué.","s":3},{"q":"Quelles lésions composent la « triade malheureuse » ?","o":["LCA + ménisque + LLI","LCA + LCP + LLE","Ménisque + LLE + rotule","LCA + rotule + tendon rotulien"],"r":0,"e":"L'association LCA, ménisque et ligament latéral interne constitue la triade malheureuse.","s":3},{"q":"Quelle affirmation sur la douleur dans la lésion du LCA est exacte ?","o":["Dans de nombreux cas, la douleur n'est pas présente","La douleur est toujours intense et permanente","La douleur est exclusivement nocturne","La douleur précède toujours le traumatisme"],"r":0,"e":"Le cours souligne que dans de nombreux cas la douleur n'est pas présente.","s":3},{"q":"Que signifie la sensation de « give away » ?","o":["Une dérobade du genou traduisant l'instabilité","Un blocage articulaire complet","Un craquement indolore normal","Une raideur matinale"],"r":0,"e":"Elle accompagne la claudication et traduit l'instabilité articulaire.","s":3},{"q":"Quels types de greffe sont utilisés dans la reconstruction du LCA ?","o":["Ischio-jambiers ou tendon rotulien","Tendon d'Achille ou fascia lata uniquement","Ligament synthétique exclusivement","Greffe osseuse iliaque"],"r":0,"e":"La greffe d'IJ ou de tendon rotulien conditionne les délais et les contre-indications.","s":3},{"q":"Dans quel cas privilégie-t-on un traitement conservateur du LCA ?","o":["Patient sans activité physique ou non disponible pour la rééducation post-opératoire","Athlète de haut niveau avec récidives","Rupture totale chez un sujet jeune sportif","Lésion associée à une instabilité majeure chez un compétiteur"],"r":0,"e":"Le conservateur dépend de l'âge, des comorbidités, de l'absence d'activité sportive et de la disponibilité pour la rééducation.","s":3},{"q":"Quelle progression de force musculaire est proposée après reconstruction du LCA ?","o":["Isométrique en phase initiale puis évolution vers CCO et CCF","Pliométrie dès la première semaine","Charges maximales en CCO immédiatement","Aucun travail de force avant 6 mois"],"r":0,"e":"FM isométrique en phase initiale puis évolution vers chaîne cinétique ouverte et fermée.","s":3},{"q":"Quelle est la fonction du LLI et du LLE ?","o":["La stabilité latérale de l'articulation du genou","Le contrôle de l'antériorisation du tibia","La transmission des charges axiales","La lubrification articulaire"],"r":0,"e":"LLI (fémoro-tibial) et LLE (fémoro-fibulaire) assurent la stabilité latérale du genou.","s":3},{"q":"Quelles sont les fonctions des ménisques ?","o":["Congruence articulaire et transmission des charges","Production de liquide synovial","Stabilité latérale du genou","Contrôle de la rotation du fémur uniquement"],"r":0,"e":"Congruence articulaire et transmission des charges compressives, de cisaillement et axiales.","s":3},{"q":"Quelle partie du ménisque est la mieux vascularisée ?","o":["Le tiers externe (zone rouge)","Le tiers interne","La corne postérieure exclusivement","Toute la surface de façon homogène"],"r":0,"e":"Le 1/3 externe (zone rouge) est le plus vascularisé ; les 2/3 restants sont nourris par diffusion passive liée à la charge axiale.","s":3},{"q":"Comment les 2/3 internes du ménisque sont-ils nourris ?","o":["Par diffusion passive liée à la charge axiale","Par des artères propres","Par le liquide céphalo-rachidien","Ils ne sont pas nourris"],"r":0,"e":"Ils sont nourris par des processus de diffusion passive liés à la charge axiale.","s":3},{"q":"Quel facteur de risque figure parmi ceux des lésions méniscales ?","o":["L'IMC","La taille","Le groupe sanguin","La latéralité"],"r":0,"e":"Les facteurs de risque cités sont l'âge, l'IMC et les lésions antérieures.","s":3},{"q":"Quelle classification n'appartient PAS aux lésions méniscales ?","o":["En anse de panier vertébrale","Longitudinale","Radiale","En anse de seau"],"r":0,"e":"Les types sont : longitudinale, radiale, horizontale, oblique, en anse de seau et complexe.","s":3},{"q":"Dans quel cas la suture méniscale est-elle privilégiée ?","o":["Lésion longitudinale aiguë, périphérique, chez un sujet jeune sans lésion ligamentaire","Lésion dégénérative chez le sujet âgé","Lésion radiale de la zone blanche","Toute lésion méniscale"],"r":0,"e":"Ces critères définissent l'indication de la suture, dont le pronostic fonctionnel est supérieur à la méniscectomie.","s":3},{"q":"Quels sont les trois sites les plus touchés par l'instabilité chronique ?","o":["L'épaule, la tibio-tarsienne et la rotule","Le coude, le poignet et la hanche","Le rachis, la hanche et le genou","Les doigts, l'ATM et le genou"],"r":0,"e":"Le cours cite l'épaule, la TT et la rotule.","s":3},{"q":"Quelle est la différence entre luxation et subluxation ?","o":["Dans la subluxation, l'os revient instantanément à sa position initiale","La subluxation est toujours chirurgicale","La luxation ne touche jamais l'épaule","La subluxation ne provoque jamais de symptômes"],"r":0,"e":"Le mécanisme est semblable, mais dans la subluxation l'os reprend spontanément sa position.","s":3},{"q":"Quel type de luxation de l'épaule est le plus fréquent ?","o":["La luxation antérieure","La luxation postérieure","La luxation inférieure","La luxation supérieure"],"r":0,"e":"La luxation antérieure représente la grande majorité des cas.","s":3},{"q":"Qu'est-ce que la lésion de Bankart ?","o":["Une avulsion du labrum antéro-inférieur","Une empreinte osseuse de la tête humérale","Une rupture du supra-épineux","Une fracture de la glène postérieure"],"r":0,"e":"Bankart = avulsion du labrum antéro-inférieur sur lequel s'insère la bande antérieure du LGHI.","s":3},{"q":"À partir de quel pourcentage un défect de Hill-Sachs prédispose-t-il à l'instabilité ?","o":["30 % de la surface articulaire humérale","10 %","50 %","5 %"],"r":0,"e":"Le défect prédispose à l'instabilité lorsqu'il dépasse 30 % de la surface articulaire humérale.","s":3},{"q":"Quand le traitement conservateur de l'instabilité gléno-humérale est-il privilégié ?","o":["Instabilité multidirectionnelle et 1ᵉʳ épisode sans autres risques associés","Sportif de haut niveau avec récidives","Lésion de Bankart avec Hill-Sachs > 30 %","Systématiquement"],"r":0,"e":"La chirurgie est envisagée en 1ʳᵉ intention chez le compétiteur de haut niveau ou en cas de récidives invalidantes.","s":3},{"q":"Qu'est-ce que la capsulite rétractile ?","o":["Une fibrose rétractile de la gléno-humérale empêchant l'écartement des surfaces articulaires","Une inflammation de la bourse sous-acromiale","Une rupture du labrum supérieur","Une calcification du supra-épineux"],"r":0,"e":"C'est une fibrose rétractile de l'articulation gléno-humérale.","s":3},{"q":"Quel est le profil épidémiologique typique de la capsulite rétractile ?","o":["Femme de plus de 60 ans, évolution traînante de 1 à 2 ans","Homme jeune sportif, évolution en 3 semaines","Enfant de 10 ans","Adulte de 30 ans après traumatisme aigu uniquement"],"r":0,"e":"Plus fréquente chez les femmes de plus de 60 ans, avec une évolution traînante jusqu'à 1 à 2 ans.","s":3},{"q":"Quel élément clinique distingue la capsulite rétractile ?","o":["Les mouvements actifs ET passifs sont globalement limités","Seuls les mouvements actifs sont limités","Seule l'abduction est limitée","Il n'y a pas de douleur nocturne"],"r":0,"e":"La limitation globale, active et passive, associée à une douleur nocturne intense en décubitus homolatéral, est caractéristique.","s":3},{"q":"Quels signes accompagnent une lésion ligamentaire de grade III ?","o":["Œdème important","Ecchymose","Grande instabilité","Impotence fonctionnelle totale","Absence d'instabilité mécanique"],"r":[0,1,2,3],"e":"Le grade III est une rupture complète : œdème important, ecchymose, grande instabilité et impotence fonctionnelle totale.","s":3},{"q":"Quelles populations sont particulièrement exposées à l'entorse de cheville ?","o":["Les personnes prédisposées à l'instabilité ligamentaire","Les pratiquants de sports à changements de direction","Les nageurs de fond","Les cyclistes sur route"],"r":[0,1],"e":"Instabilité ligamentaire préexistante et sports à changements de direction (tennis, padel, basket, football, handball).","s":3},{"q":"Quels signes et symptômes retrouve-t-on dans l'entorse de cheville ?","o":["Douleur","Œdème","Hématome","Incapacité fonctionnelle à la marche","Instabilité","Paralysie des releveurs du pied"],"r":[0,1,2,3,4],"e":"Douleur, œdème, hématome, incapacité à la marche, instabilité et crépitation constituent le tableau.","s":3},{"q":"Qu'est-ce qui doit faire évoquer une lésion de la syndesmose plutôt qu'une entorse latérale simple ?","o":["Un traumatisme à haute vitesse avec douleur très intense et squeeze test positif","Un œdème modéré du bord externe","Une douleur nocturne isolée","Une raideur matinale"],"r":0,"e":"La lésion de syndesmose survient sur traumatisme à haute vitesse, avec une douleur très intense et un squeeze test positif.","s":3},{"q":"Quelles stratégies composent l'intervention dans l'entorse de cheville ?","o":["PEACE & LOVE","Techniques d'immobilisation sélective","Travail de force musculaire et rééducation sensori-motrice","Pliométrie","Immobilisation plâtrée systématique de six semaines"],"r":[0,1,2,3],"e":"PEACE & LOVE, immobilisation sélective, force et RSM (particulièrement soulignée) puis pliométrie.","s":3},{"q":"Quel mécanisme récent est évoqué dans la survenue des lésions du LCA ?","o":["Un mécanisme neurocognitif lié aux tâches multiples en situation sportive","Une origine strictement génétique","Une carence en collagène de type I","Un mécanisme purement inflammatoire"],"r":0,"e":"Au-delà du pivot et du changement de direction, des données récentes suggèrent un mécanisme neurocognitif associé à la double tâche en sport.","s":3},{"q":"Dans quels sports la lésion du LCA est-elle fréquente ?","o":["Football","Ski","Natation","Cyclisme sur piste"],"r":[0,1],"e":"Sports avec sauts, changements rapides de direction et décélérations : football et ski sont cités.","s":3},{"q":"Que décrit le grade 1 d'une lésion du LCA ?","o":["Une modification de la longueur du ligament, le genou restant stable","Une rupture partielle","Une rupture totale avec instabilité","Une avulsion osseuse"],"r":0,"e":"Grade 1 : le ligament est allongé mais maintient encore la stabilité du genou. Le grade 2 (rupture partielle) est le moins fréquent, le grade 3 est la rupture totale.","s":3},{"q":"Quels signes accompagnent fréquemment une rupture du LCA ?","o":["Sensation de claquement","Épanchement articulaire","Claudication et sensation de « give away »","Douleur systématiquement intense"],"r":[0,1,2],"e":"Claquement, épanchement, claudication et dérobement. La douleur, elle, est souvent absente.","s":3},{"q":"Quelles stratégies de kinésithérapie s'appliquent après reconstruction du LCA ?","o":["PEACE & LOVE en phase initiale","Mobilité et flexibilité en respectant les délais post-opératoires","Force musculaire, rééducation sensori-motrice et pliométrie","Éducation","Reprise du pivot dès la deuxième semaine"],"r":[0,1,2,3],"e":"PEACE & LOVE, mobilité et travail de la cicatrice dans le respect des délais, force, RSM, pliométrie et éducation. Le type de greffe conditionne les délais.","s":3},{"q":"Quelles unions osseuses les ligaments latéraux du genou assurent-ils ?","o":["LLI : union fémoro-tibiale","LLE : union fémoro-fibulaire","LLI : union fémoro-fibulaire","LLE : union tibio-fibulaire"],"r":[0,1],"e":"Le LLI unit fémur et tibia, le LLE unit fémur et fibula. Ensemble ils assurent la stabilité latérale du genou.","s":3},{"q":"Quels examens participent au diagnostic d'une lésion du LLI ou du LLE ?","o":["Histoire clinique","Tests spécifiques","Radiographie","IRM","Électromyographie"],"r":[0,1,2,3],"e":"Histoire clinique, tests spécifiques, radiographie (pour les altérations osseuses associées à une contusion) et IRM.","s":3},{"q":"De quoi dépend le pourcentage de charge transmis par les ménisques ?","o":["Du degré de flexion du genou","De l'âge du patient","De l'IMC","De la vitesse du mouvement"],"r":0,"e":"Les ménisques assurent congruence et transmission des charges compressives, de cisaillement et axiales ; la part transmise varie selon le degré de flexion du genou.","s":3},{"q":"Quels mécanismes sont à l'origine des lésions méniscales ?","o":["Un mécanisme essentiellement dégénératif","Des tâches à grandes amplitudes de flexion du genou","Un mécanisme traumatique, surtout en chaîne cinétique fermée","Une origine infectieuse"],"r":[0,1,2],"e":"Essentiellement dégénératif, favorisé par les grandes flexions, et traumatique surtout en chaîne cinétique fermée.","s":3},{"q":"Quelles conditions réunit la suture méniscale idéale ?","o":["Lésion longitudinale","Lésion de préférence aiguë","Sujet jeune","Absence d'altérations ligamentaires","Localisation en région périphérique","Lésion radiale étendue à la zone blanche"],"r":[0,1,2,3,4],"e":"Les cinq conditions sont citées, et la suture offre alors un pronostic fonctionnel supérieur à la méniscectomie.","s":3},{"q":"Quelle stratégie est particulièrement soulignée dans la prise en charge des lésions méniscales ?","o":["L'éducation","L'électrothérapie","L'immobilisation stricte","La pharmacothérapie au long cours"],"r":0,"e":"L'éducation est marquée « +++ », avec PEACE & LOVE, mobilité, force musculaire et rééducation sensori-motrice.","s":3},{"q":"Quels sites sont typiquement concernés par la subluxation ?","o":["L'épaule","La rotule, en particulier chez la femme","Le coude","Les doigts"],"r":[0,1],"e":"Subluxation : épaule et rotule (chez la femme). Coude et doigts sont cités pour la luxation.","s":3},{"q":"De quoi dépend la récupération après une luxation ?","o":["De l'étendue de la lésion des tissus mous environnants","Uniquement de la rapidité de la réduction","De l'âge exclusivement","Du type d'anesthésie utilisé"],"r":0,"e":"La récupération dépend avant tout de l'étendue des lésions des tissus mous environnants.","s":3},{"q":"Quelles structures peuvent être en cause dans une instabilité gléno-humérale ?","o":["Le labrum","Le cartilage glénoïdien et huméral","Les ligaments gléno-huméraux et la capsule","La coiffe des rotateurs et le tendon du biceps","Le fascia plantaire"],"r":[0,1,2,3],"e":"Toutes ces structures sont citées comme causes possibles d'instabilité gléno-humérale.","s":3},{"q":"Quels sont les principes d'intervention dans la capsulite rétractile en phase aiguë ?","o":["Pharmacothérapie : anti-inflammatoires et corticoïdes","Thérapie manuelle, électrothérapie et exercices à visée antalgique","Manipulation sous anesthésie générale si nécessaire","Renforcement maximal immédiat en amplitude complète"],"r":[0,1,2],"e":"Anti-inflammatoires et corticoïdes en phase inflammatoire marquée, kinésithérapie antalgique, et manipulation sous anesthésie générale en recours chirurgical.","s":3},{"q":"Quelle est la fonction de la bourse séreuse ?","o":["Diminuer le frottement des tendons et muscles sur les proéminences osseuses","Produire du collagène","Assurer la contraction musculaire","Transmettre l'influx nerveux"],"r":0,"e":"C'est sa fonction mécanique principale.","s":4},{"q":"Quelle bourse ne figure PAS parmi les plus fréquemment affectées ?","o":["La bourse sous-scapulaire","La bourse sous-acromiale","La bourse trochantérienne","La bourse pré-patellaire"],"r":0,"e":"Les plus touchées sont les bourses sous-acromiale, olécrânienne, trochantérienne, pré-patellaire et calcanéenne.","s":4},{"q":"Qu'est-ce qui irrite les nocicepteurs dans la bursite ?","o":["L'accumulation de liquide synovial","La calcification du tendon","La rupture des fibres musculaires","La compression nerveuse"],"r":0,"e":"L'inflammation provoque la production de grandes quantités de liquide synovial dont l'accumulation irrite les nocicepteurs locaux.","s":4},{"q":"Comment débute typiquement une bursite sous-acromiale ?","o":["De façon soudaine, avec des signes inflammatoires marqués","De façon progressive sur plusieurs années","Sans aucun symptôme","Uniquement après 60 ans"],"r":0,"e":"Début soudain, signes inflammatoires marqués et impotence fonctionnelle totale avec postures antalgiques.","s":4},{"q":"Où se situe la douleur de la bursite trochantérienne en phase aiguë ?","o":["Intense et précise sur la face externe de la hanche","Diffuse dans tout le membre inférieur","À la face antérieure du genou","Dans la région inguinale"],"r":0,"e":"En phase aiguë la douleur est intense et précise sur la face externe ; elle devient indéfinie et étendue dans la chronicité.","s":4},{"q":"Quels mouvements résistés reproduisent la douleur de la bursite trochantérienne ?","o":["Abduction et rotation externe","Adduction et rotation interne","Flexion et extension de genou","Flexion plantaire"],"r":0,"e":"Douleur à la palpation du bord supérieur du trochanter et aux mouvements résistés d'abduction et rotation externe.","s":4},{"q":"Le kyste de Baker correspond à l'atteinte de quelle bourse ?","o":["La bourse des gastrocnémiens / semi-membraneux","La bourse pré-patellaire","La bourse trochantérienne","La bourse olécrânienne"],"r":0,"e":"C'est le remplissage ou l'inflammation de la bourse des gastrocnémiens/semi-membraneux, à la face postérieure du genou.","s":4},{"q":"Devant un kyste de Baker avec douleur sévère et œdème exacerbé du mollet, que faut-il écarter en urgence ?","o":["Une thrombose veineuse profonde","Une fracture de fatigue","Une rupture du LCA","Une bursite pré-patellaire"],"r":0,"e":"Il est urgent d'écarter une TVP et d'orienter vers les urgences.","s":4},{"q":"Quelle intervention kinésithérapique est proposée pour le kyste de Baker ?","o":["Compression par bande élastique et travail isométrique du quadriceps","Renforcement excentrique maximal des ischio-jambiers","Massage profond de la fosse poplitée","Immobilisation plâtrée"],"r":0,"e":"Après aspiration éventuelle : compression par bande élastique et travail isométrique du quadriceps.","s":4},{"q":"Au-dessus de quel angle les mouvements répétitifs exposent-ils au conflit sous-acromial ?","o":["90°","30°","150°","45°"],"r":0,"e":"Ce sont les individus exécutant des mouvements répétitifs au-dessus de 90° qui sont concernés.","s":4},{"q":"Quel élément correspond à un conflit sous-acromial primaire ?","o":["Un acromion de type III","Une tendinopathie associée","Une bursite associée","Une rupture méniscale"],"r":0,"e":"Primaire : acromion type III, laxité capsulaire, déséquilibres de la coiffe, causes rhumatologiques. Secondaire : associé à tendinopathie ou bursite.","s":4},{"q":"Vers quelle complication le conflit sous-acromial peut-il évoluer ?","o":["La rupture du tendon du supra-épineux","La capsulite rétractile obligatoire","La luxation postérieure","L'arthrose acromio-claviculaire isolée"],"r":0,"e":"L'évolution peut mener à une rupture de la coiffe / du supra-épineux, fréquente chez l'homme de plus de 50 ans.","s":4},{"q":"Après combien de temps d'échec du traitement conservateur l'acromioplastie est-elle envisagée ?","o":["6 mois","2 semaines","2 ans","6 semaines"],"r":0,"e":"L'acromioplastie est indiquée quand le traitement conservateur du conflit échoue après 6 mois.","s":4},{"q":"Quel est l'objectif de l'acromioplastie ?","o":["Augmenter l'espace sous-acromial","Réduire la mobilité de l'épaule","Fusionner l'articulation gléno-humérale","Retirer le labrum"],"r":0,"e":"L'objectif est l'augmentation de l'espace sous-acromial ; on peut y associer une réparation de la coiffe ou de la capsule.","s":4},{"q":"Où se situe la lésion SLAP ?","o":["Au labrum de la glène, près de l'insertion de la longue portion du biceps","À la face inférieure de l'acromion","Sur le trochiter","Dans la gouttière bicipitale distale"],"r":0,"e":"SLAP = Superior Labrum Anterior Posterior, près de l'insertion de la longue portion du biceps.","s":4},{"q":"Quelle perte d'amplitude est typique de la lésion SLAP ?","o":["La rotation interne","L'abduction","La flexion","L'extension"],"r":0,"e":"On observe une perte de ROM en rotation interne, associée à une perte de force de la coiffe.","s":4},{"q":"Quelle conduite s'applique à une lésion SLAP de type III ?","o":["La chirurgie","Le traitement conservateur seul","L'abstention thérapeutique","L'immobilisation stricte de 6 mois"],"r":0,"e":"Type I : conservateur. Type II : chirurgie si échec du conservateur. Type III : chirurgie.","s":4},{"q":"Quel nerf est comprimé dans le syndrome du canal carpien ?","o":["Le nerf médian","Le nerf ulnaire","Le nerf radial","Le nerf musculo-cutané"],"r":0,"e":"Il s'agit de la compression du nerf médian lors de sa traversée du poignet.","s":4},{"q":"Quel examen confirme le diagnostic de syndrome du canal carpien ?","o":["L'électromyographie","La radiographie standard","L'échographie Doppler","La scintigraphie"],"r":0,"e":"Le diagnostic est confirmé par électromyographie.","s":4},{"q":"Comment évoluent les paresthésies du syndrome du canal carpien ?","o":["Nocturnes et matinales, elles cèdent au cours de la journée","Elles n'apparaissent qu'en fin de journée","Elles sont permanentes dès le début","Elles ne concernent que le pouce"],"r":0,"e":"Paresthésies nocturnes et matinales qui cèdent au cours de la journée, avec perte de dextérité.","s":4},{"q":"Quelle condition n'est PAS un facteur associé au syndrome du canal carpien ?","o":["L'ostéoporose","La grossesse","Le diabète","La polyarthrite rhumatoïde"],"r":0,"e":"Les facteurs cités sont la grossesse, le diabète, la polyarthrite rhumatoïde, la goutte et l'arthrose.","s":4},{"q":"Quelle attelle est proposée dans le syndrome du canal carpien ?","o":["Une attelle de positionnement nocturne","Une attelle dynamique diurne","Un plâtre circulaire","Une orthèse plantaire"],"r":0,"e":"Les attelles de positionnement nocturne font partie des stratégies d'intervention.","s":4},{"q":"Quelles situations aggravent le syndrome fémoro-patellaire ?","o":["Monter et descendre les escaliers et les longues périodes assis","Le décubitus dorsal","La marche en terrain plat uniquement","La flexion cervicale"],"r":0,"e":"Il s'aggrave dans les escaliers, au passage flexion-extension en charge et après de longues périodes assis.","s":4},{"q":"Qu'est-ce que le syndrome de la plica ?","o":["Un repli de la membrane synoviale qui ne régresse pas en phase embryonnaire","Une inflammation de la bourse pré-patellaire","Une lésion du cartilage rotulien","Une rupture partielle du tendon rotulien"],"r":0,"e":"C'est un repli synovial persistant, siège d'un processus inflammatoire idiopathique, macro- ou microtraumatique.","s":4},{"q":"Où se situe la douleur du syndrome de la bandelette ilio-tibiale ?","o":["Dans la zone latérale externe du genou","À la face antérieure du genou","Dans le creux poplité","À la face interne de la cuisse"],"r":0,"e":"Il s'agit d'un processus inflammatoire de la portion distale de la bandelette, avec douleur latérale externe.","s":4},{"q":"Quelle population est la plus concernée par le syndrome de la bandelette ilio-tibiale ?","o":["Les coureurs","Les nageurs","Les haltérophiles","Les joueurs de tennis"],"r":0,"e":"C'est une lésion commune chez les coureurs, liée à la friction et à l'irritation de la structure.","s":4},{"q":"Où s'insère le fascia plantaire dont l'inflammation cause la fasciite plantaire ?","o":["Sur le calcanéus (insertion postérieure)","Sur les métatarsiens","Sur le talus","Sur le naviculaire"],"r":0,"e":"Il s'agit de l'inflammation du fascia plantaire à son insertion postérieure sur le calcanéus.","s":4},{"q":"Quand la douleur de la fasciite plantaire est-elle typiquement déclenchée ?","o":["À la mise en charge, surtout au réveil","Uniquement le soir","Pendant le sommeil","Au repos assis"],"r":0,"e":"Douleur sous-calcanéenne déclenchée par la charge surtout au réveil, s'aggravant progressivement à la marche.","s":4},{"q":"Quel mouvement peut exacerber la douleur de la fasciite plantaire ?","o":["L'extension des orteils","La flexion du genou","La rotation de hanche","L'inversion du pied"],"r":0,"e":"L'extension des orteils met le fascia en tension et peut exacerber la douleur.","s":4},{"q":"Quels sont les types de conflit fémoro-acétabulaire ?","o":["CAM, Pincer ou mixte","Type I, II et III","Antérieur, postérieur, latéral","Primaire et secondaire uniquement"],"r":0,"e":"Le conflit fémoro-acétabulaire se décline en CAM, Pincer ou mixte ; c'est la dysfonction de hanche la plus fréquente du jeune adulte.","s":4},{"q":"Comment définit-on la biomécanique dans ce contexte ?","o":["L'interaction des forces internes et externes mécaniques dans le mouvement humain","L'étude des seules forces musculaires","La description anatomique des articulations","L'analyse de la consommation énergétique du mouvement"],"r":0,"e":"La biomécanique est l'interaction des forces internes et externes mécaniques dans le mouvement humain.","s":4},{"q":"Pourquoi l'examen subjectif et objectif est-il central dans les dysfonctions biomécaniques ?","o":["Parce que le mécanisme lésionnel est un déséquilibre de facteurs internes et/ou externes qu'il faut identifier","Parce qu'il remplace l'imagerie","Parce qu'il permet de chiffrer la douleur","Parce qu'il détermine la durée d'immobilisation"],"r":0,"e":"La lésion résulte d'un déséquilibre des facteurs internes et/ou externes : il faut donc les évaluer, d'où l'importance des examens subjectif et objectif.","s":4},{"q":"Quels mécanismes peuvent provoquer une bursite ?","o":["Traumatisme","Mouvements répétitifs et surcharge","Conditions rhumatologiques","Processus infectieux","Carence en vitamine D"],"r":[0,1,2,3],"e":"Les quatre mécanismes sont cités : traumatique, microtraumatique/surcharge, rhumatologique et infectieux.","s":4},{"q":"Quel est le tableau clinique d'une bursite ?","o":["Douleur sévère","Œdème de la bourse","Limitation marquée des amplitudes articulaires","Paresthésies distales"],"r":[0,1,2],"e":"Douleur sévère, œdème de la bourse et limitation marquée des amplitudes. Les paresthésies évoquent une atteinte nerveuse.","s":4},{"q":"Quelles interventions sont proposées dans la bursite ?","o":["PEACE & love","Pharmacothérapie","Kinésithérapie","Éducation","Immobilisation plâtrée de six semaines"],"r":[0,1,2,3],"e":"PEACE & love, pharmacothérapie, kinésithérapie et éducation.","s":4},{"q":"Pourquoi un diagnostic différentiel est-il nécessaire entre bursite sous-acromiale et tendinopathie de la coiffe ?","o":["Parce que leurs facteurs de risque et leur examen objectif sont semblables","Parce qu'elles ont le même traitement chirurgical","Parce que l'imagerie ne les distingue jamais","Parce qu'elles touchent des tranches d'âge opposées"],"r":0,"e":"Facteurs de risque et examen objectif sont semblables, d'où la nécessité d'un diagnostic différentiel.","s":4},{"q":"Comment évolue la douleur de la bursite trochantérienne vers la chronicité ?","o":["Elle devient indéfinie et étendue à la fesse, la crête iliaque, la face externe de cuisse et de jambe","Elle se limite progressivement au trochanter","Elle disparaît la nuit","Elle migre vers la face antérieure de cuisse"],"r":0,"e":"Précise et intense sur la face externe de hanche en phase aiguë, elle devient indéfinie et étendue dans la chronicité.","s":4},{"q":"Quelles situations aggravent la douleur de la bursite trochantérienne ?","o":["La marche","Les rotations de hanche","Le décubitus homolatéral la nuit","La position assise prolongée"],"r":[0,1,2],"e":"Marche, rotations de hanche et décubitus homolatéral nocturne. Le syndrome fémoro-patellaire, lui, est aggravé par la position assise prolongée.","s":4},{"q":"À quelles lésions le kyste de Baker est-il associé ?","o":["Lésion méniscale","Lésion cartilagineuse","Maladies rhumatologiques","Rupture du LCA isolée"],"r":[0,1,2],"e":"Le kyste de Baker s'associe aux lésions dégénératives du genou : méniscale, cartilagineuse, et aux maladies rhumatologiques.","s":4},{"q":"Quels signes cliniques accompagnent un kyste de Baker ?","o":["Sensation d'inflammation et de tension poplitée s'aggravant à la marche","Raideur matinale","Épanchement associé","Paresthésies du pied"],"r":[0,1,2],"e":"Tension poplitée aggravée à la marche, raideur matinale et épanchement. Les paresthésies ne font pas partie du tableau.","s":4},{"q":"Quel conflit sous-acromial est qualifié de secondaire ?","o":["Celui associé à une tendinopathie ou à des bursites","Celui lié à un acromion de type III","Celui lié à une laxité capsulaire","Celui d'origine rhumatologique"],"r":0,"e":"Le conflit secondaire est associé à une tendinopathie ou à des bursites. Acromion type III, laxité capsulaire, déséquilibres de coiffe et causes rhumatologiques définissent le conflit primaire.","s":4},{"q":"Quels mouvements sont douloureux dans le conflit sous-acromial ?","o":["Flexion","Abduction","Adduction horizontale","Rotation interne","Extension de coude"],"r":[0,1,2,3],"e":"Flexion, abduction, adduction horizontale et rotation interne de l'épaule.","s":4},{"q":"Par quelles voies l'acromioplastie peut-elle être réalisée ?","o":["Arthroscopique","Ouverte","Percutanée sous scanner","Par voie postérieure exclusivement"],"r":[0,1],"e":"L'acromioplastie se pratique par voie arthroscopique ou ouverte.","s":4},{"q":"Quels gestes peuvent être associés à une acromioplastie ?","o":["Réparation du tendon de la coiffe","Traitement de la bursite","Réparation de dommages capsulaires","Prothèse totale d'épaule"],"r":[0,1,2],"e":"Pendant la décompression, on peut réparer la coiffe, traiter la bursite ou réparer des dommages capsulaires.","s":4},{"q":"Quels mécanismes peuvent être à l'origine d'une lésion SLAP ?","o":["Dégénératif, associé à des lésions de Bankart ou de la coiffe après 40 ans","Instabilité antérieure de l'épaule","Lésion de la longue portion du biceps","Surcharge par mouvements répétitifs en flexion/abduction et rotation externe","Compression du nerf médian au poignet"],"r":[0,1,2,3],"e":"Quatre mécanismes : dégénératif, instabilité antérieure, lésion de la longue portion du biceps et surcharge.","s":4},{"q":"Quels signes composent le tableau clinique d'une lésion SLAP ?","o":["Douleur lors des mouvements au-dessus de la tête","Sensation de « clic » avec inconfort","Perte de ROM en rotation interne","Perte de force des muscles de la coiffe","Difficulté à dormir sur le côté homolatéral","Paresthésies des trois premiers doigts"],"r":[0,1,2,3,4],"e":"Les cinq signes sont cités dans la fiche.","s":4},{"q":"Quelle conduite s'applique à une lésion SLAP de type II ?","o":["Chirurgie à envisager si le traitement conservateur échoue","Traitement conservateur exclusif","Chirurgie d'emblée","Abstention"],"r":0,"e":"Type I : conservateur. Type II : chirurgie envisagée en cas d'échec du conservateur. Type III : chirurgie.","s":4},{"q":"Quelles populations sont exposées au syndrome du canal carpien ?","o":["Tâches domestiques fréquentes entre 40 et 60 ans","Travail prolongé à l'ordinateur","Grossesse","Diabète, polyarthrite rhumatoïde, goutte, arthrose","Pratique intensive de la course à pied"],"r":[0,1,2,3],"e":"Toutes ces situations sont citées comme facteurs associés.","s":4},{"q":"Quelles interventions sont proposées dans le syndrome fémoro-patellaire ?","o":["Modification de l'activité et rééducation du mouvement","Immobilisation sélective","Force musculaire sélective et flexibilité sélective","Orthèses","Acromioplastie"],"r":[0,1,2,3],"e":"Modification de l'activité, immobilisation sélective, travail sélectif de force et de flexibilité, et orthèses.","s":4},{"q":"Quel est l'objectif du traitement conservateur, habituellement de premier choix, dans le conflit fémoro-acétabulaire ?","o":["Diminuer les signes inflammatoires, rééduquer les schémas musculaires, améliorer mobilité et fonction","Immobiliser la hanche six semaines","Préparer systématiquement l'arthroscopie","Limiter définitivement les amplitudes de hanche"],"r":0,"e":"Le conservateur vise à réduire l'inflammation (PEACE & LOVE), rééduquer les schémas musculaires par l'exercice, améliorer la mobilité et restaurer la fonction (marche, escaliers, conduite, activité physique).","s":4},{"q":"Quelle cellule est responsable de la résorption osseuse ?","o":["L'ostéoclaste","L'ostéoblaste","Le chondrocyte","Le fibroblaste"],"r":0,"e":"Les ostéoclastes assurent la résorption ; les ostéoblastes synthétisent le collagène et contribuent à la minéralisation.","s":5},{"q":"Quelle est la proportion de collagène dans la matrice osseuse ?","o":["90 %","50 %","20 %","10 %"],"r":0,"e":"La matrice contient 90 % de collagène, avec prédominance du type I.","s":5},{"q":"De quelle vitamine dépend l'ostéocalcine ?","o":["La vitamine D","La vitamine K","La vitamine C","La vitamine B12"],"r":0,"e":"L'ostéocalcine est dépendante de la vitamine D ; l'acide γ-carboxyglutamique nécessite la vitamine K.","s":5},{"q":"Quelle vitamine est nécessaire à la synthèse de l'acide γ-carboxyglutamique ?","o":["La vitamine K","La vitamine D","La vitamine A","La vitamine E"],"r":0,"e":"Cet acide, fixateur du calcium, nécessite la vitamine K pour être synthétisé.","s":5},{"q":"Quel processus osseux perdure tout au long de la vie ?","o":["Le remodelage","La croissance","Le modelage","La fermeture du cartilage de conjugaison"],"r":0,"e":"Croissance et modelage cessent à la fermeture du cartilage de conjugaison ; remodelage et réparation perdurent toute la vie.","s":5},{"q":"Que définit le remodelage osseux ?","o":["L'adaptation de la masse et de la géométrie osseuse aux exigences fonctionnelles et mécaniques","L'augmentation de la masse osseuse pendant la croissance","La simple modification de la forme de l'os","La minéralisation initiale"],"r":0,"e":"C'est l'adaptation de la masse et de la géométrie aux exigences fonctionnelles et mécaniques.","s":5},{"q":"Quelle fracture est typique de l'enfant ?","o":["La fracture en bois vert","La fracture du col du fémur","La fracture de la clavicule chez l'adulte","La fracture pathologique sur ostéoporose"],"r":0,"e":"Chez l'enfant : extrémité distale du radius et fracture en bois vert (incomplète).","s":5},{"q":"Quelle fracture est la plus caractéristique de la personne âgée ?","o":["Le col du fémur","La clavicule","Le tibia distal","La rotule"],"r":0,"e":"Chez l'adulte : clavicule, radius distal, poignet, col du fémur (personnes âgées +++) et tibia.","s":5},{"q":"Quelle classification est utilisée pour les fractures de l'enfant touchant le cartilage de croissance ?","o":["Salter-Harris","BAMIC","Salter-Cobb","Outerbridge"],"r":0,"e":"La classification de Salter-Harris est celle citée dans le cours.","s":5},{"q":"Quelle est la durée de la phase inflammatoire de la consolidation osseuse ?","o":["1 à 2 semaines","1 à 2 jours","6 semaines","3 mois"],"r":0,"e":"La phase inflammatoire dure 1 à 2 semaines et représente 10 % du processus, avec fonction totalement restreinte.","s":5},{"q":"Quelle activité cellulaire domine la phase inflammatoire de la consolidation ?","o":["L'activité ostéoclastique","L'activité ostéoblastique","L'activité chondroblastique","L'activité fibroblastique exclusivement"],"r":0,"e":"Réaction inflammatoire, hématome, débridement de l'os et activité ostéoclastique.","s":5},{"q":"Quel pourcentage du processus de consolidation représente le remodelage ?","o":["50 %","10 %","20 %","30 %"],"r":0,"e":"Inflammatoire 10 %, cal mou 20 %, cal dur 20 %, remodelage 50 %.","s":5},{"q":"À quelle étape la ligne de fracture disparaît-elle complètement ?","o":["Au remodelage","Au cal mou","À la phase inflammatoire","Dès la première semaine"],"r":0,"e":"Au cal dur la ligne commence à disparaître ; elle disparaît au remodelage, avec formation d'os lamellaire.","s":5},{"q":"Quel est le délai de consolidation d'une fracture du 1/3 distal du tibia ?","o":["16 à 20 semaines","6 semaines","8 à 12 semaines","2 semaines"],"r":0,"e":"1/3 distal du tibia : union 8-10 semaines, consolidation 16-20 semaines.","s":5},{"q":"Quel est le délai d'union d'une fracture du 1/3 proximal de l'humérus ?","o":["3 semaines","6 semaines","12 semaines","1 semaine"],"r":0,"e":"1/3 proximal de l'humérus : union à 3 semaines, consolidation à 6 semaines.","s":5},{"q":"Quelle méthode d'immobilisation non chirurgicale est la plus fréquente ?","o":["L'immobilisation plâtrée","La fixation externe","La traction","La fixation interne"],"r":0,"e":"Le plâtre (ou fibre de verre) est la méthode non chirurgicale la plus fréquente.","s":5},{"q":"Quel risque est spécifiquement associé à la fixation externe ?","o":["L'ostéomyélite et l'infection des vis","La myosite ossifiante","La luxation","La thrombose artérielle"],"r":0,"e":"La fixation externe expose au risque d'ostéomyélite et d'infection des vis, mais permet une meilleure gestion quand la peau est très endommagée.","s":5},{"q":"Quel principe s'applique au renforcement musculaire avant le remodelage osseux ?","o":["Ne pas utiliser de charges élevées ni de longs bras de levier","Utiliser systématiquement des charges maximales","Éviter toute mobilisation des segments voisins","Interdire toute contraction musculaire"],"r":0,"e":"Il faut proscrire les charges élevées et les longs bras de levier avant que l'os ne soit remodelé.","s":5},{"q":"Quelle complication ne figure PAS parmi celles des fractures ?","o":["La capsulite rétractile gléno-humérale","Le cal vicieux","La non-union","La myosite ossifiante"],"r":0,"e":"Les complications citées sont : retard d'union, non-union, cal vicieux, dysmétries, raideur, nécrose, problèmes autonomiques et myosite ossifiante.","s":5},{"q":"De quoi est composé le cartilage articulaire ?","o":["De chondrocytes et d'une matrice de protéoglycanes, collagène et eau","D'ostéoblastes et de sels minéraux","De fibroblastes et d'élastine","De myofibroblastes et de collagène de type III"],"r":0,"e":"Cellules (chondrocytes) + matrice extracellulaire faite de protéoglycanes, collagène et eau.","s":5},{"q":"Pourquoi la réparation du cartilage est-elle très limitée ?","o":["Absence de réseau vasculaire et réponse cellulaire limitée","Excès de vascularisation","Prolifération cellulaire trop rapide","Absence totale de matrice"],"r":0,"e":"Ce sont les deux obstacles majeurs cités dans le cours.","s":5},{"q":"Qu'est-ce qui distingue une lésion cartilagineuse profonde ?","o":["Elle atteint l'os sous-chondral et donne accès au réseau vasculaire","Elle guérit sans séquelle","Elle ne concerne que les chondroblastes","Elle est toujours asymptomatique"],"r":0,"e":"L'accès au réseau vasculaire osseux permet la présence des 3 phases de réponse à la lésion tissulaire.","s":5},{"q":"Quelle affirmation sur l'arthrose est correcte ?","o":["C'est un processus dégénératif non inflammatoire des articulations portantes","C'est une maladie auto-immune inflammatoire","Elle touche surtout les petites articulations des mains","Elle progresse toujours de façon brutale"],"r":0,"e":"L'arthrose découle d'un processus dégénératif non inflammatoire affectant essentiellement les articulations portantes.","s":5},{"q":"Comment évolue la douleur arthrosique ?","o":["Elle diminue avec le repos et s'aggrave avec la charge","Elle s'aggrave au repos et cède à l'effort","Elle est permanente et indépendante de l'activité","Elle est exclusivement nocturne"],"r":0,"e":"Douleur qui diminue avec le repos, s'aggrave avec la charge, intense au réveil avec tendance à diminuer.","s":5},{"q":"Quelles amplitudes sont typiquement perdues dans la coxarthrose ?","o":["Flexion, abduction et rotation interne","Extension et rotation externe uniquement","Toutes les amplitudes de façon égale","Aucune amplitude n'est perdue"],"r":0,"e":"La coxarthrose limite la flexion, l'abduction et la rotation interne, avec une douleur irradiant de l'aine vers la cuisse.","s":5},{"q":"Quelle est la durée de vie moyenne d'une prothèse de genou ?","o":["15 à 20 ans","20 à 25 ans","10 ans","5 ans"],"r":0,"e":"Hanche 20-25 ans, genou 15-20 ans, épaule inversée environ 10 ans.","s":5},{"q":"Quand introduit-on la charge après une prothèse de hanche non cimentée ?","o":["Entre 6 et 12 semaines","Dès le 1ᵉʳ jour post-opératoire","À 6 mois","Jamais"],"r":0,"e":"Cimentée : charge dès le 1ᵉʳ jour. Non cimentée : 6 à 12 semaines.","s":5},{"q":"Quelles positions sont luxantes après une PTH par voie postérolatérale ?","o":["Flexion de plus de 90°, adduction et rotation interne","Hyperextension, rotation externe et adduction","Abduction et rotation externe","Extension complète et abduction"],"r":0,"e":"Postérolatérale : flexion > 90°, adduction, rotation interne. Antérolatérale et latérale : hyperextension, rotation externe, adduction.","s":5},{"q":"À quel délai débute la mobilisation passive continue (CPM) après une prothèse de genou ?","o":["À 48 h","À 2 semaines","À 6 semaines","Immédiatement en salle de réveil"],"r":0,"e":"La CPM est débutée à 48 h, le patient étant positionné en décubitus dorsal, membre surélevé et en extension.","s":5},{"q":"Quel est le pronostic attendu en flexion active après une prothèse de genou ?","o":["100°","60°","140°","30°"],"r":0,"e":"Pronostic : extension complète, 100° de flexion active, appui en charge totale, stabilité et autonomie dans les AVQ.","s":5},{"q":"Quelles sont les fonctions des ostéoblastes ?","o":["Synthétiser le collagène","Contribuer à la minéralisation","Médier la résorption des ostéoclastes","Synthétiser des facteurs de croissance","Résorber directement la matrice osseuse"],"r":[0,1,2,3],"e":"L'ostéoblaste synthétise le collagène, minéralise, médie la résorption ostéoclastique et produit des facteurs de croissance. C'est l'ostéoclaste qui résorbe.","s":5},{"q":"Quels facteurs régulent le remodelage osseux ?","o":["Génétiques","Mécaniques","Vasculaires","Nutritionnels","Hormonaux","Immunologiques"],"r":[0,1,2,3,4],"e":"Cinq familles de facteurs : génétiques, mécaniques, vasculaires, nutritionnels et hormonaux.","s":5},{"q":"Quelle est la différence entre croissance et modelage osseux ?","o":["La croissance augmente la masse osseuse, le modelage en modifie la forme","La croissance modifie la forme, le modelage augmente la masse","Les deux perdurent toute la vie","Le modelage ne concerne que l'os cortical"],"r":0,"e":"Croissance = augmentation de la masse osseuse ; modelage = modification de la forme. Tous deux cessent à la fermeture du cartilage de conjugaison, contrairement au remodelage et à la réparation.","s":5},{"q":"Quelles causes de fracture s'ajoutent au traumatisme direct ou indirect ?","o":["Pathologie associée : ostéoporose, désordres métaboliques, tumeurs","Stress ou fatigue par charges répétées ou excessives","Avulsion par arrachement d'un fragment osseux","Carence isolée en vitamine C"],"r":[0,1,2],"e":"Pathologie associée, stress/fatigue et avulsion complètent les mécanismes traumatiques directs et indirects.","s":5},{"q":"Pourquoi l'incidence des fractures augmente-t-elle chez la femme après la ménopause ?","o":["Par diminution de la densité osseuse liée à l'ostéoporose","Par augmentation de l'activité ostéoblastique","Par excès de vitamine D","Par raccourcissement du cartilage de conjugaison"],"r":0,"e":"La chute de densité osseuse post-ménopausique (ostéoporose) explique la plus grande incidence de fractures chez la femme.","s":5},{"q":"Quels signes et symptômes évoquent une fracture ?","o":["Douleur intense augmentant avec le mouvement","Œdème marqué et déformation du contour","Position anormale du segment","Sensation de crépitation","Paresthésies distales isolées"],"r":[0,1,2,3],"e":"Douleur augmentée au mouvement, œdème, déformation, perte de fonction, position anormale et crépitation.","s":5},{"q":"Quelle est la fonction du segment pendant la phase de cal dur ?","o":["Initiée","Totalement restreinte","Restreinte","Presque normale à normale"],"r":0,"e":"Inflammatoire : fonction totalement restreinte. Cal mou : restreinte. Cal dur : initiée. Remodelage : presque normale à normale.","s":5},{"q":"Qu'est-ce qui caractérise la phase de cal mou ?","o":["Activité ostéoblastique produisant tissu fibreux, cartilage et une petite quantité d'os","Activité ostéoclastique et hématome","Os réticulé immature en cours de minéralisation","Os lamellaire et résorption de l'excès de cal"],"r":0,"e":"Le cal mou (20 %) est marqué par l'activité ostéoblastique : tissu fibreux, cartilage et un peu d'os.","s":5},{"q":"Quel est le délai de consolidation d'une fracture du 1/3 distal du radius ou du cubitus ?","o":["12 semaines","6 semaines","8 à 12 semaines","16 à 20 semaines"],"r":0,"e":"Union à 6 semaines, consolidation à 12 semaines pour le 1/3 distal du radius/cubitus.","s":5},{"q":"Quels sont les avantages et inconvénients de la fixation interne ?","o":["Elle permet une mobilisation précoce générale et spécifique","Elle inflige un traumatisme additionnel aux structures adjacentes","Elle expose à des complications chirurgicales et à l'infection","Elle est préférable quand la peau est très endommagée"],"r":[0,1,2],"e":"La fixation interne autorise la mobilisation précoce mais ajoute un traumatisme et des risques infectieux. C'est la fixation externe qui est préférée quand la peau est très abîmée.","s":5},{"q":"Pourquoi faut-il limiter le mouvement au niveau du trait de fracture ?","o":["Il peut causer des dommages additionnels à l'os, aux vaisseaux, aux nerfs et aux tissus mous","Il accélère la résorption ostéoclastique","Il empêche la formation de l'hématome","Il augmente la minéralisation"],"r":0,"e":"Le mouvement au foyer peut léser davantage l'os et les structures voisines : vaisseaux sanguins, nerfs et tissus mous.","s":5},{"q":"Quelles conséquences l'immobilisation et le non-usage entraînent-ils pour le patient fracturé ?","o":["Diminution des amplitudes par rétraction capsulo-ligamentaire et myofasciale","Diminution de la force","Altérations sensori-motrices","Altération de la fonction cardio-respiratoire","Augmentation de la densité osseuse"],"r":[0,1,2,3],"e":"Perte d'amplitude, de force, altérations sensori-motrices, retentissement cardio-respiratoire, vasculaire et cutané, et baisse de la capacité fonctionnelle.","s":5},{"q":"Quels principes guident l'intervention après une fracture ?","o":["Mobiliser si possible les segments non affectés","Respecter les délais de réparation et de formation du cal","Surveiller le type de marche pour éviter la surcharge de la zone lésée","Éviter charges élevées et longs bras de levier avant le remodelage","Débuter d'emblée un renforcement maximal"],"r":[0,1,2,3],"e":"Mobiliser ce qui peut l'être, respecter les délais du cal, adapter la marche et proscrire charges élevées et longs bras de levier avant le remodelage osseux.","s":5},{"q":"Quelles cellules assurent la réparation d'une lésion cartilagineuse superficielle ?","o":["Les chondroblastes, dont la prolifération est limitée","Les ostéoclastes","Les fibroblastes du périoste","Les cellules souches médullaires"],"r":0,"e":"La lésion superficielle dépend exclusivement des chondroblastes, dont la prolifération est limitée — d'où une réparation très pauvre.","s":5},{"q":"Que se passe-t-il lors d'une lésion cartilagineuse profonde ?","o":["Des cellules indifférenciées migrent, se transforment en chondrocytes et synthétisent la matrice","Le cartilage se régénère à l'identique","Aucune réponse cellulaire n'est possible","Seuls les ostéoclastes interviennent"],"r":0,"e":"L'atteinte de l'os sous-chondral ouvre l'accès au réseau vasculaire : des cellules indifférenciées migrent et se différencient en chondrocytes. Mais le tissu de substitution n'est jamais identique à l'original.","s":5},{"q":"Quels facteurs prédisposent à l'arthrose ?","o":["Malformations congénitales comme la dysplasie de hanche","Irrégularité des surfaces articulaires après traumatisme","Altération de l'alignement du membre inférieur","Obésité","Exercice avec impact","Consommation excessive de calcium"],"r":[0,1,2,3,4],"e":"Tous ces facteurs sont cités, avec la sénescence articulaire et les altérations pathologiques articulaires.","s":5},{"q":"Pourquoi l'arthrose peut-elle rester longtemps asymptomatique ?","o":["Les symptômes n'apparaissent que lorsque l'os et la capsule commencent à être atteints","Parce que le cartilage est très innervé","Parce que la douleur est masquée par l'inflammation","Parce que le diagnostic est purement radiologique"],"r":0,"e":"Jusqu'à un certain degré l'arthrose est asymptomatique : les symptômes surviennent quand l'os et la capsule sont touchés. Le début est insidieux et l'évolution lente.","s":5},{"q":"Quels éléments composent le traitement conservateur de l'arthrose ?","o":["Médication","Viscosupplémentation ou PRP","Kinésithérapie et exercice physique","Contrôle du poids, éducation et aides à la marche","Arthrodèse"],"r":[0,1,2,3],"e":"Le conservateur vise à diminuer douleur et raideur. Arthrodèse, ostéotomie et arthroplastie relèvent du chirurgical.","s":5},{"q":"Quelles positions faut-il éviter après une PTH par voie antérolatérale ou latérale ?","o":["Hyperextension","Rotation externe","Adduction","Flexion à plus de 90°"],"r":[0,1,2],"e":"Voie antérolatérale et latérale : éviter hyperextension, rotation externe et adduction. La flexion au-delà de 90° concerne la voie postérolatérale.","s":5},{"q":"D'où vient la dénomination « inversée » de la prothèse d'épaule ?","o":["La concavité se situe au niveau de la glène","La tête humérale est remplacée par une tige droite","L'implant est posé par voie postérieure","La rotation de l'épaule est inversée"],"r":0,"e":"Dans la prothèse inversée, la concavité se trouve au niveau de la glène — d'où le nom. Elle est indiquée en cas de fracture complexe, de coiffe irréparable ou de dégénérescence avancée.","s":5},{"q":"Quelle caractéristique appartient à la dysfonction vertébrale mécanique ?","o":["Plaintes aggravées par l'effort et soulagées par le repos","Douleur soulagée par le mouvement","Raideur matinale prolongée","Atteinte systémique constante"],"r":0,"e":"La dysfonction mécanique s'aggrave à l'effort, se soulage au repos, avec une raideur de courte durée et sans atteinte systémique.","s":6},{"q":"Quelle caractéristique oriente vers une dysfonction inflammatoire ?","o":["Douleur qui réveille la nuit et est soulagée par le mouvement","Douleur soulagée par le repos","Raideur matinale de courte durée","Radiographies toujours normales"],"r":0,"e":"L'inflammatoire réveille le patient la nuit, est soulagée par le mouvement, avec une raideur matinale prolongée et une atteinte systémique.","s":6},{"q":"Quel signe évoque une dysfonction maligne ou infectieuse ?","o":["Absence de rythme défini et absence de facteurs de soulagement","Soulagement complet au repos","Aggravation uniquement à l'effort","Raideur matinale de 5 minutes"],"r":0,"e":"Douleur permanente très invalidante, sans rythme ni facteur de soulagement, faible réponse à la pharmacothérapie, asthénie, amaigrissement, fièvre.","s":6},{"q":"Quel élément est un red flag de fracture ?","o":["L'usage prolongé de corticoïdes","La kinésiophobie","Le manque de soutien social","La satisfaction au travail"],"r":0,"e":"Red flags de fracture : traumatisme et usage prolongé de corticoïdes.","s":6},{"q":"Quel élément est un red flag de malignité ?","o":["Une perte de poids soudaine","De la fièvre","Un traumatisme récent","Des croyances de kinésiophobie"],"r":0,"e":"Malignité : antécédents de maladie oncologique et perte de poids soudaine. La fièvre oriente vers l'infection.","s":6},{"q":"Lequel de ces éléments est un yellow flag ?","o":["Les croyances conduisant à la kinésiophobie","Une fièvre inexpliquée","Un antécédent de cancer","Un traumatisme récent"],"r":0,"e":"Yellow flags : kinésiophobie, manque de soutien social, traitements non conformes aux meilleures pratiques.","s":6},{"q":"Comment définit-on un syndrome radiculaire ?","o":["Une compression ou une inflammation des racines nerveuses","Une inflammation de la capsule articulaire","Une dégénérescence du corps vertébral seul","Une contracture musculaire paravertébrale"],"r":0,"e":"C'est la compression ou l'inflammation des racines nerveuses.","s":6},{"q":"Quel type de douleur caractérise le syndrome radiculaire ?","o":["Douleur profonde et bien localisée avec irradiation le long du dermatome","Douleur superficielle mal systématisée","Douleur exclusivement au repos","Douleur bilatérale symétrique"],"r":0,"e":"Douleur profonde, bien localisée, irradiée le long du dermatome, avec sensation de brûlure et paresthésies.","s":6},{"q":"Quelle cause peut provoquer une compression directe d'une racine nerveuse ?","o":["Une ostéophytose de l'articulation interapophysaire postérieure","Une contracture musculaire simple","Un déficit en vitamine D","Une bursite trochantérienne"],"r":0,"e":"Compression ou traction directe : dégénérescence ou rupture discale, ostéophytose de l'AIP.","s":6},{"q":"Depuis combien de temps une cervicalgie non spécifique doit-elle évoluer pour être retenue ?","o":["Au moins 1 jour","Au moins 3 mois","Au moins 12 semaines","Au moins 1 an"],"r":0,"e":"Le cours définit la cervicalgie non spécifique comme évoluant depuis au moins 1 jour, avec impact sur les AVQ.","s":6},{"q":"L'atteinte dans la cervico-brachialgie est le plus souvent :","o":["Mono-radiculaire","Pluri-radiculaire","Médullaire","Purement musculaire"],"r":0,"e":"L'atteinte est fréquemment mono-radiculaire, souvent liée à un processus dégénératif cervical.","s":6},{"q":"Quel facteur extrinsèque est associé à la cervicalgie ?","o":["La satisfaction au travail","La densité osseuse","La longueur des membres inférieurs","Le groupe sanguin"],"r":0,"e":"Facteurs extrinsèques cités : soutien social, satisfaction au travail, niveaux de stress, dépression.","s":6},{"q":"Quelle relation faut-il évaluer en cas de cervicalgie ?","o":["La relation cervicales-ATM","La relation hanche-genou","La relation épaule-coude","La relation lombaire-sacro-iliaque"],"r":0,"e":"Le cours insiste sur le dépistage des red flags et l'évaluation des relations cervicales-ATM.","s":6},{"q":"Quelle est l'étiologie la plus fréquente de la lombalgie ?","o":["Idiopathique (non spécifique)","Le spondylolisthésis","La sténose du canal lombaire","L'arthrose de l'AIP"],"r":0,"e":"L'étiologie idiopathique/non spécifique est la première ; les autres sont des conditions cliniques associées.","s":6},{"q":"À partir de quelle durée une lombalgie est-elle considérée comme chronique ?","o":["Plus de 12 semaines","Plus de 3 semaines","Plus de 6 mois","Plus de 1 an"],"r":0,"e":"Au-delà de 12 semaines, la lombalgie devient chronique et constitue un problème majeur de santé publique.","s":6},{"q":"Quelle caractéristique distingue l'irradiation de la lombalgie simple ?","o":["Territoires mal définis, sans altération sensitive ni de la force objective","Trajet dermatomal précis avec déficit moteur","Paresthésies constantes du pied","Abolition systématique des réflexes"],"r":0,"e":"L'irradiation de la lombalgie se fait sur des territoires mal définis, sans altération sensitive, des réflexes ni de la force objective.","s":6},{"q":"Quel élément est un facteur de risque de chronicité de la lombalgie ?","o":["La quantité et la fréquence des crises sur 12 mois","La taille du patient","Le niveau de force du quadriceps","La densité minérale osseuse"],"r":0,"e":"La quantité/fréquence des crises sur 12 mois est explicitement citée comme facteur de risque de chronicité.","s":6},{"q":"À quels niveaux se situent 90 à 95 % des conflits disco-radiculaires de la lombosciatalgie ?","o":["L5 et S1","L1 et L2","T12 et L1","S2 et S3"],"r":0,"e":"La lombosciatalgie est liée à des conflits disco-radiculaires L5-S1 dans 90 à 95 % des cas.","s":6},{"q":"Quel trajet suit la douleur de la lombosciatalgie ?","o":["Région fessière, face postérieure ou postéro-externe de cuisse, jambe et pied","Face antérieure de la cuisse jusqu'au genou uniquement","Région inguinale et face interne de la cuisse","Région dorsale et thoracique"],"r":0,"e":"C'est le trajet décrit ; fréquemment la douleur ne présente pas le trajet complet.","s":6},{"q":"La lombosciatalgie est-elle habituellement bilatérale ?","o":["Non, elle est très rarement bilatérale","Oui, presque toujours","Oui, dans 50 % des cas","Toujours bilatérale au stade chronique"],"r":0,"e":"Le cours précise qu'elle est très rarement bilatérale.","s":6},{"q":"Quelle différence sépare lombalgie et lombosciatalgie sur le plan neurologique ?","o":["La lombosciatalgie présente des altérations de l'examen neurologique","La lombalgie abolit les réflexes","Aucune différence neurologique","La lombosciatalgie n'a jamais de paresthésies"],"r":0,"e":"La lombosciatalgie s'accompagne d'altérations des réflexes, de la sensibilité et de la force ; la lombalgie non.","s":6},{"q":"Comment définit-on une scoliose structurale ?","o":["Courbure latérale supérieure à 10° avec rotation des corps vertébraux","Toute déviation latérale du rachis","Une courbure réductible à la flexion","Une cyphose supérieure à 40°"],"r":0,"e":"Scoliose structurale : courbure latérale > 10° accompagnée d'une rotation des corps vertébraux, avec tendance évolutive.","s":6},{"q":"Qu'est-ce qui caractérise l'attitude scoliotique ?","o":["Le rachis a une flexibilité suffisante pour retrouver sa forme physiologique","Elle comporte une rotation vertébrale fixée","Elle dépasse toujours 30°","Elle nécessite systématiquement une chirurgie"],"r":0,"e":"L'attitude scoliotique est réductible : le rachis retrouve sa forme physiologique.","s":6},{"q":"Quelle est la prévalence de la scoliose idiopathique chez les enfants de 10-16 ans ?","o":["2 à 4 %","10 à 15 %","0,1 %","20 %"],"r":0,"e":"Elle est présente chez 2 à 4 % des enfants de 10-16 ans, plus fréquente et plus grave chez les filles.","s":6},{"q":"Comment évoluent les courbures de moins de 30° arrivées à maturité osseuse ?","o":["Elles n'ont pas tendance à progresser","Elles progressent de 1° par an","Elles régressent spontanément","Elles nécessitent toujours une chirurgie"],"r":0,"e":"Les courbures ≤ 30° à maturité ne progressent pas ; celles ≥ 50° progressent de 1° par an.","s":6},{"q":"Quel outil mesure l'angle de la courbure du tronc ?","o":["Le scoliomètre","Le goniomètre","L'inclinomètre lombaire","Le dynamomètre"],"r":0,"e":"Le scoliomètre mesure l'angle de la courbure du tronc ; l'angle de Cobb se mesure sur radiographie.","s":6},{"q":"À partir de quelle courbure une orthèse est-elle indiquée ?","o":["≥ 25°","≥ 10°","≥ 40°","≥ 50°"],"r":0,"e":"Entre 20 et 29° : surveiller et mettre une orthèse pour les courbures ≥ 25°.","s":6},{"q":"À partir de quelle courbure la chirurgie est-elle indiquée ?","o":["≥ 40°","≥ 20°","≥ 30°","≥ 60°"],"r":0,"e":"À partir de 40°, il faut adresser pour chirurgie.","s":6},{"q":"Quel est l'effet réel des orthèses dans la scoliose ?","o":["Elles ne corrigent pas la scoliose mais préviennent sa progression de 60 à 74 %","Elles corrigent définitivement la courbure","Elles n'ont aucun effet démontré","Elles remplacent la chirurgie dans tous les cas"],"r":0,"e":"Les orthèses préviennent la progression de l'ordre de 60 à 74 % ; plus de 16 h/jour donne de meilleurs résultats.","s":6},{"q":"Quel est le délai de retour à l'activité physique après correction chirurgicale d'une scoliose ?","o":["9 à 12 mois","2 semaines","4 à 5 jours","3 mois"],"r":0,"e":"Hospitalisation 4-5 jours, retour à l'école en 2 semaines, retour à l'activité physique en 9 à 12 mois en évitant les sports de contact.","s":6},{"q":"Quelles caractéristiques appartiennent à une dysfonction vertébrale mécanique ?","o":["Plaintes aggravées par l'effort et soulagées par le repos","Raideur matinale et post-repos de courte durée","Absence d'atteinte systémique","Radiographies normales ou avec altérations dégénératives","Soulagement par le mouvement après réveil nocturne"],"r":[0,1,2,3],"e":"La dysfonction mécanique s'aggrave à l'effort, se soulage au repos, donne une raideur brève, n'a pas d'atteinte systémique et montre des radiographies normales ou dégénératives. Le réveil nocturne soulagé par le mouvement est inflammatoire.","s":6},{"q":"Quels éléments évoquent une dysfonction vertébrale maligne ou infectieuse ?","o":["Absence de rythme défini et douleur permanente très invalidante","Absence de facteurs de soulagement","Faible réponse à la pharmacothérapie conventionnelle","Asthénie, amaigrissement, fièvre","Soulagement net par le repos"],"r":[0,1,2,3],"e":"Pas de rythme, douleur permanente, pas de soulagement, mauvaise réponse aux antalgiques et signes généraux. Le soulagement par le repos caractérise au contraire la douleur mécanique.","s":6},{"q":"Quel red flag oriente vers une infection ?","o":["Fièvre et antécédents de maladies infectieuses comme le VIH","Usage prolongé de corticoïdes","Perte de poids soudaine","Antécédents de maladie oncologique"],"r":0,"e":"Fièvre et antécédents infectieux (VIH par exemple) sont les red flags d'infection. Les corticoïdes évoquent la fracture, la perte de poids et les antécédents oncologiques la malignité.","s":6},{"q":"Quels sont les yellow flags identifiés par Oliveira et al. (2018) ?","o":["Croyances conduisant à la kinésiophobie","Manque de soutien social","Traitements non conformes aux meilleures pratiques","Antécédent de traumatisme récent"],"r":[0,1,2],"e":"Trois yellow flags : kinésiophobie, manque de soutien social et traitements non conformes aux meilleures pratiques. Le traumatisme est un red flag de fracture.","s":6},{"q":"Quels mécanismes peuvent produire un syndrome radiculaire ?","o":["Compression ou traction directe par dégénérescence ou rupture discale","Ostéophytose de l'articulation interapophysaire postérieure","Inflammation de la structure nerveuse par microtraumatismes de l'agent compressif","Carence en vitamine D"],"r":[0,1,2],"e":"Compression/traction directe (disque, ostéophytose de l'AIP) et inflammation nerveuse liée aux microtraumatismes de l'agent compressif.","s":6},{"q":"Dans un syndrome radiculaire, les réflexes et la force sont :","o":["Parfois atteints, parfois non","Toujours abolis","Toujours normaux","Atteints uniquement en cas de fièvre"],"r":0,"e":"La fiche précise que les réflexes et la force peuvent être ou non affectés dans le syndrome radiculaire.","s":6},{"q":"Quels symptômes composent le tableau de la cervico-brachialgie ?","o":["Douleur intense pouvant s'exacerber la nuit","Augmentation avec les mouvements du rachis cervical et du membre supérieur","Paresthésies du territoire atteint","Diminution de la mobilité cervicale","Insomnies associées","Perte de la sensibilité thermo-algique des membres inférieurs"],"r":[0,1,2,3,4],"e":"Les cinq symptômes sont cités.","s":6},{"q":"Quelles atteintes neurales peuvent accompagner une cervico-brachialgie ?","o":["Altérations sensitives","Perte de force","Altérations des réflexes myotendineux","Perte de l'odorat"],"r":[0,1,2],"e":"Altérations sensitives, perte de force et altérations des réflexes myotendineux sont les trois atteintes neurales possibles.","s":6},{"q":"Quelles interventions sont proposées dans la cervicalgie (Verhagen, 2021) ?","o":["Exercice : hydrothérapie, flexibilité, force des stabilisateurs cervicaux","Thérapie manuelle par mobilisation","Massage","Médicaments","Immobilisation par collier permanent"],"r":[0,1,2,3],"e":"Exercice, thérapie manuelle, massage, médicaments et chirurgie. L'immobilisation permanente n'est pas retenue.","s":6},{"q":"Quelles conditions cliniques peuvent être associées à une lombalgie ?","o":["Spondylolisthésis","Sténose du canal lombaire","Pathologie du disque intervertébral","Arthrose de l'articulation interapophysaire postérieure","Scoliose posturale"],"r":[0,1,2,3],"e":"Spondylolisthésis, sténose lombaire, pathologie discale et arthrose de l'AIP. La lombalgie reste toutefois le plus souvent idiopathique et non spécifique.","s":6},{"q":"Quels éléments composent le tableau clinique de la lombalgie ?","o":["Début progressif, sauf en situation de traumatisme","Kinésiophobie et postures antalgiques","Augmentation de la tension des muscles proximaux","Intensité très variable","Altération objective de la force et des réflexes"],"r":[0,1,2,3],"e":"Début progressif, kinésiophobie, tension musculaire proximale et intensité variable. L'absence d'altération sensitive, des réflexes et de la force objective distingue la lombalgie de la lombosciatalgie.","s":6},{"q":"Que dit l'épidémiologie de la lombalgie ?","o":["Tous les individus auront au moins une fois dans leur vie une lombalgie d'évolution bénigne","Elle ne touche que les travailleurs manuels","Elle est rare avant 50 ans","Elle évolue presque toujours vers la chronicité"],"r":0,"e":"Les données épidémiologiques indiquent que chacun connaîtra au moins un épisode de lombalgie, d'évolution bénigne dans la majorité des cas.","s":6},{"q":"Quelles sont les étiologies de la lombosciatalgie ?","o":["Conflit disco-radiculaire","Sténose du canal médullaire","Arthrose des articulations interapophysaires postérieures","Spondylolisthésis","Scoliose idiopathique"],"r":[0,1,2,3],"e":"Conflit disco-radiculaire, sténose du canal, arthrose des AIP et spondylolisthésis.","s":6},{"q":"Quelles particularités cliniques caractérisent la lombosciatalgie ?","o":["Douleur intense cédant mal au repos et s'exacerbant la nuit","Altérations de l'examen neurologique (réflexes, sensibilité, force)","Altérations du schéma de marche avec claudication","La douleur ne présente fréquemment pas le trajet complet","Atteinte bilatérale habituelle"],"r":[0,1,2,3],"e":"Douleur nocturne mal soulagée, atteinte neurologique objective, claudication et trajet souvent incomplet. L'atteinte bilatérale est au contraire très rare.","s":6},{"q":"Quelles sont les causes secondaires de scoliose structurale ?","o":["Inégalité de longueur des membres inférieurs","Dysplasie de hanche","Ostéogenèse imparfaite","Posture maintenue au bureau"],"r":[0,1,2],"e":"Inégalité de longueur des membres, dysplasie de hanche et ostéogenèse imparfaite. La posture maintenue cause plutôt une attitude scoliotique, réductible.","s":6},{"q":"Chez qui la scoliose idiopathique est-elle plus fréquente et plus grave ?","o":["Chez les filles","Chez les garçons","Indifféremment selon le sexe","Chez les enfants de moins de 5 ans"],"r":0,"e":"La scoliose structurale idiopathique, d'origine génétique, est plus fréquente et plus grave chez les filles.","s":6},{"q":"Comment progressent les courbures de 50° ou plus arrivées à maturité osseuse ?","o":["D'environ 1° par an","Elles ne progressent plus","De 5° par an","De façon imprévisible et brutale"],"r":0,"e":"Les courbures ≥ 50° à la maturité progressent de l'ordre de 1° par an, contrairement à celles ≤ 30° qui n'ont pas tendance à évoluer.","s":6},{"q":"Quels outils permettent d'évaluer une scoliose ?","o":["Le test d'Adams","Le scoliomètre","L'angle de Cobb sur radiographie","Le squeeze test"],"r":[0,1,2],"e":"Test d'Adams, scoliomètre et angle de Cobb. Le squeeze test explore la syndesmose de la cheville.","s":6},{"q":"Pour une courbure de 22°, quelle est la conduite recommandée ?","o":["Surveiller, radiographier tous les 6 mois et adresser ; orthèse si la courbure atteint 25°","Chirurgie","Orthèse immédiate quelle que soit la valeur","Aucune surveillance nécessaire"],"r":0,"e":"Entre 20 et 29° : radiographie tous les 6 mois, adresser, surveiller, et poser une orthèse pour les courbures ≥ 25°.","s":6},{"q":"Quelles précisions sont exactes concernant le port d'orthèse dans la scoliose ?","o":["Plus de 16 h par jour donne de meilleurs résultats","L'orthèse la plus courante est la Boston","Elle est utilisée jusqu'à ce qu'une chirurgie devienne nécessaire","Elle corrige durablement la courbure"],"r":[0,1,2],"e":"Plus de 16 h/jour, modèle Boston, jusqu'à l'indication chirurgicale. L'orthèse ne corrige pas la scoliose : elle en prévient la progression de 60 à 74 %.","s":6},{"q":"Où siège la lésion primitive de la polyarthrite rhumatoïde ?","o":["Au niveau de la membrane synoviale","Au niveau du cartilage articulaire","Au niveau de l'os sous-chondral","Au niveau du tendon"],"r":0,"e":"La lésion primitive est une synovite proliférative et destructrice de la membrane synoviale, évoluant par poussées.","s":7},{"q":"Quel est le profil articulaire typique de la polyarthrite rhumatoïde ?","o":["Polyarthrite symétrique destructrice des petites articulations","Monoarthrite asymétrique des grosses articulations","Atteinte exclusive du rachis","Arthrose des articulations portantes"],"r":0,"e":"PR = polyarthrite symétrique destructrice, petites articulations et synoviales (poignet, mains, pieds), avec effets systémiques.","s":7},{"q":"Quelle altération radiographique fait partie des critères de classification de la PR ?","o":["Ostéopénie et érosions","Ostéophytose marginale","Colonne en bambou","Pincement des articulations portantes"],"r":0,"e":"Les critères incluent les altérations radiographiques à type d'ostéopénie et d'érosions.","s":7},{"q":"Combien d'articulations au minimum doivent être atteintes selon les critères de classification de la PR ?","o":["3 ou plus","1","5 ou plus","10 ou plus"],"r":0,"e":"Arthrite de 3 articulations ou plus figure parmi les critères.","s":7},{"q":"Quel est le pic d'incidence du lupus érythémateux disséminé ?","o":["Entre 15 et 40 ans","Entre 50 et 65 ans","Après 70 ans","Avant 10 ans"],"r":0,"e":"Le lupus est prédominant chez la femme avec un pic d'incidence entre 15 et 40 ans.","s":7},{"q":"Quel facteur hormonal aggrave le lupus ?","o":["Les œstrogènes","La testostérone","La parathormone","Le cortisol"],"r":0,"e":"La présence d'œstrogènes aggrave la maladie.","s":7},{"q":"Quel pourcentage de patients lupiques présente des plaintes articulaires ?","o":["90 %","50 %","30 %","10 %"],"r":0,"e":"Les plaintes articulaires surviennent chez 90 % des personnes atteintes.","s":7},{"q":"Quel type de polyarthrite est le plus fréquent dans le lupus ?","o":["Polyarthrite non érosive des petites articulations","Polyarthrite érosive destructrice","Monoarthrite du genou","Arthrite des sacro-iliaques"],"r":0,"e":"Les plus fréquentes sont les polyarthrites non érosives des petites articulations des mains, pieds et poignets.","s":7},{"q":"Quelle éruption cutanée est caractéristique du lupus ?","o":["L'éruption en aile de papillon","Le psoriasis en plaques","L'érythème noueux","Le purpura pétéchial"],"r":0,"e":"L'éruption en aile de papillon et la photosensibilité sont caractéristiques.","s":7},{"q":"Quel cristal se dépose dans la goutte ?","o":["L'urate monosodique","Le pyrophosphate de calcium","L'hydroxyapatite","L'oxalate de calcium"],"r":0,"e":"La goutte résulte du dépôt de cristaux d'urate monosodique consécutif à une hyperuricémie.","s":7},{"q":"Au-delà de quelle concentration sérique d'acide urique le risque de goutte augmente-t-il ?","o":["7,0 mg/dl","3,0 mg/dl","12,0 mg/dl","1,0 mg/dl"],"r":0,"e":"Le risque augmente avec l'élévation de la concentration sérique d'acide urique au-dessus de 7,0 mg/dl.","s":7},{"q":"Comment débutent typiquement les premières crises de goutte ?","o":["Mono-articulaires, avec un début soudain la nuit ou au petit matin","Polyarticulaires et symétriques","Progressivement sur plusieurs mois","Exclusivement après un traumatisme"],"r":0,"e":"Les premiers épisodes sont mono-articulaires avec un début soudain pendant la nuit ou au petit matin.","s":7},{"q":"En combien de temps une crise de goutte se résout-elle spontanément ?","o":["3 à 10 jours","24 heures","4 à 6 semaines","3 mois"],"r":0,"e":"Résolution spontanée en 3 à 10 jours, avec desquamation cutanée locale.","s":7},{"q":"Quel médicament spécifique est cité dans le traitement de la goutte ?","o":["La colchicine","Le méthotrexate","L'insuline","Le paracétamol seul"],"r":0,"e":"Pharmacothérapie : anti-inflammatoires, colchicine, corticoïdes.","s":7},{"q":"Quel aliment faut-il éviter en cas de goutte ?","o":["Les fruits de mer et le gibier (riches en purines)","Les produits laitiers","Les légumes verts","Le pain complet"],"r":0,"e":"Il faut éviter les purines : viande de porc, alcool, gibier, fruits de mer.","s":7},{"q":"Quel marqueur génétique est associé à la spondylarthrite ankylosante ?","o":["HLA-B27","HLA-DR4","BRCA1","APOE4"],"r":0,"e":"Association au marqueur HLA-B27 dans 70 à 90 % des cas.","s":7},{"q":"Que signifie « séronégative » pour la spondylarthrite ankylosante ?","o":["Il n'existe pas de facteurs rhumatoïdes dans le liquide séreux","Il n'y a pas d'inflammation","Le HLA-B27 est absent","La VS est normale"],"r":0,"e":"Séronégative = absence de facteurs rhumatoïdes dans le liquide séreux.","s":7},{"q":"Quel est le sens de progression de la spondylarthrite ankylosante ?","o":["Ascendant : sacro-iliaques, lombaires, dorsales puis cervicales","Descendant : cervicales vers sacro-iliaques","Uniquement thoracique","Aléatoire"],"r":0,"e":"C'est une arthropathie inflammatoire chronique ascendante progressive.","s":7},{"q":"Que sont les syndesmophytes dans la spondylarthrite ankylosante ?","o":["Des ponts osseux donnant l'aspect de colonne en bambou","Des érosions articulaires","Des dépôts calciques tendineux","Des nodules sous-cutanés"],"r":0,"e":"La formation de ponts osseux et de syndesmophytes donne l'aspect radiologique de colonne en bambou.","s":7},{"q":"Quelle posture est typique de la spondylarthrite ankylosante ?","o":["Cyphose thoracique augmentée, protraction du menton, rectitude lombaire","Hyperlordose lombaire marquée","Scoliose à double courbure","Cyphose lombaire isolée"],"r":0,"e":"Cyphose thoracique augmentée, protraction du menton, rectitude de la lordose lombaire et léger flexum des genoux et de la hanche.","s":7},{"q":"Quel est le pronostic vital de la spondylarthrite ankylosante ?","o":["Elle ne compromet pas l'espérance de vie","Elle réduit l'espérance de vie de 10 ans","Elle est rapidement fatale","Le pronostic est réservé"],"r":0,"e":"Malgré une incapacité progressive, la maladie ne compromet pas l'espérance de vie : bon pronostic.","s":7},{"q":"Combien de points douloureux au minimum sont requis pour le diagnostic de fibromyalgie ?","o":["11 sur 18","5 sur 12","18 sur 18","3 sur 10"],"r":0,"e":"Au moins 11 des 18 points douloureux à la pression digitale bilatérale, sans facteurs rhumatoïdes.","s":7},{"q":"Comment définit-on la fibromyalgie ?","o":["Une dysfonction autonome et neuro-endocrine","Une maladie auto-immune destructrice","Une arthropathie séronégative","Une pathologie dégénérative du cartilage"],"r":0,"e":"C'est une dysfonction autonome et neuro-endocrine, avec douleur diffuse chronique, troubles du sommeil et fatigue.","s":7},{"q":"Quel est l'effet de l'exercice dans la fibromyalgie ?","o":["Il améliore le tonus parasympathique et réduit le nombre de points douloureux","Il aggrave systématiquement les symptômes","Il n'a aucun effet démontré","Il est contre-indiqué"],"r":0,"e":"L'exercice améliore le tonus parasympathique, la perception de la douleur, la force, réduit les points douloureux et améliore dépression, anxiété et qualité de vie.","s":7},{"q":"Quelle est la prévalence des fractures ostéoporotiques chez la femme post-ménopausée ?","o":["1 sur 3","1 sur 10","1 sur 20","1 sur 2"],"r":0,"e":"1 femme sur 3 en post-ménopause et 1 homme sur 5 après 65 ans subiront au moins 1 fracture ostéoporotique.","s":7},{"q":"Quel T-score définit l'ostéoporose ?","o":["Inférieur à −2,5","Entre −1 et −2,5","Supérieur à −1","Supérieur à 0"],"r":0,"e":"T-score > −1 : normal ; entre −1 et −2,5 : ostéopénie ; < −2,5 : ostéoporose.","s":7},{"q":"Quelles fractures caractérisent l'ostéoporose de type I ?","o":["Fractures de Colles et vertébrales","Fractures de hanche et d'humérus","Fractures du tibia","Fractures de la clavicule"],"r":0,"e":"Type I (post-ménopause, 50-65 ans) : fractures de Colles et vertébrales. Type II (après 65 ans) : hanche et humérus.","s":7},{"q":"Quels sites sont explorés par la DEXA ?","o":["Rachis lombaire L1-L4, col du fémur et extrémité distale du radius","Crâne et mandibule","Sternum et côtes","Calcanéus uniquement"],"r":0,"e":"Ce sont les trois sites de mesure cités dans le cours.","s":7},{"q":"Quel est l'effet de l'exercice physique dans l'ostéoporose ?","o":["Il stimule l'activité des ostéoblastes et prévient les chutes","Il stimule les ostéoclastes","Il est contre-indiqué","Il n'agit que sur la douleur"],"r":0,"e":"L'exercice stimule l'activité des ostéoblastes et contribue à la prévention des chutes.","s":7},{"q":"Quelle adaptation de l'exercice s'impose en cas de rétinopathie diabétique ?","o":["Éviter les pressions systoliques élevées et les inclinaisons tête plus basse que la ceinture","Privilégier les charges maximales","Favoriser les activités à fort impact","Interdire toute activité physique"],"r":0,"e":"Il faut éviter les pressions systoliques élevées, l'entraînement de force à charges élevées, le fort impact, les efforts exténuants des membres supérieurs et les inclinaisons tête basse.","s":7},{"q":"Quels sont les principes généraux communs d'intervention dans les conditions rhumatologiques ?","o":["Traitement symptomatique","Augmenter ou maintenir la capacité fonctionnelle","Éducation et conseil","Immobilisation prolongée des articulations atteintes"],"r":[0,1,2],"e":"Trois principes communs : symptomatique, capacité fonctionnelle, éducation et conseil.","s":7},{"q":"Quel est le mode de début des plaintes selon la pathologie rhumatologique ?","o":["Polyarthrite rhumatoïde : insidieux ou soudain","Goutte : soudain","Spondylarthrite ankylosante : insidieux","Fibromyalgie : par crises","Lupus : toujours insidieux"],"r":[0,1,2,3],"e":"PR : insidieux ou soudain · lupus : soudain, par poussées · goutte : soudain · spondylarthrite : insidieux · fibromyalgie : par crises.","s":7},{"q":"Quelles articulations la polyarthrite rhumatoïde touche-t-elle préférentiellement ?","o":["Le poignet","Les mains","Les pieds","Les grosses articulations portantes"],"r":[0,1,2],"e":"La PR touche les petites articulations et synoviales : poignet, mains et pieds.","s":7},{"q":"Quels critères de classification de la polyarthrite rhumatoïde sont cités ?","o":["Raideur matinale","Arthrite symétrique","Nodules sous-cutanés","Facteurs rhumatoïdes sériques","Présence de HLA-B27"],"r":[0,1,2,3],"e":"Raideur matinale, arthrite d'au moins 3 articulations, arthrite des mains, arthrite symétrique, nodules sous-cutanés, facteurs rhumatoïdes et altérations radiographiques. HLA-B27 concerne la spondylarthrite.","s":7},{"q":"Quelle est l'étiologie de la polyarthrite rhumatoïde ?","o":["Multifactorielle : facteurs génétiques et non génétiques, avec réponse immunitaire persistante chez un sujet susceptible","Strictement génétique","Strictement infectieuse","Purement mécanique"],"r":0,"e":"Étiologie multifactorielle : génétique et non génétique (environnementaux, endocriniens, infectieux), avec une réponse immunitaire persistante chez l'individu génétiquement susceptible.","s":7},{"q":"Quels objectifs sont poursuivis dans la prise en charge de la polyarthrite rhumatoïde ?","o":["Survivre le plus longtemps possible avec la meilleure qualité de vie","Éviter l'incapacité","Vivre avec le moins de plaintes possible","Un traitement autant que possible exempt d'effets indésirables et à coût raisonnable","Obtenir une rémission radiologique complète en trois mois"],"r":[0,1,2,3],"e":"Les quatre objectifs sont énoncés dans la fiche.","s":7},{"q":"Quels facteurs environnementaux sont impliqués dans le lupus ?","o":["Certains médicaments","Le rayonnement UV","Les virus","Le tabagisme passif exclusivement"],"r":[0,1,2],"e":"Médicaments, rayonnement UV et virus sont les facteurs environnementaux cités, aux côtés des facteurs immunologiques, génétiques et hormonaux.","s":7},{"q":"Quel est le pronostic du lupus érythémateux disséminé ?","o":["Évolution par poussées successives de gravité variable, diagnostic difficile, pronostic réservé","Guérison complète en quelques mois","Évolution linéaire et prévisible","Pronostic excellent sans traitement"],"r":0,"e":"Poussées successives de gravité variable, diagnostic difficile et pronostic réservé.","s":7},{"q":"Quelles articulations la goutte peut-elle atteindre, au-delà des orteils ?","o":["Les doigts","La tibio-tarsienne","Le poignet","Le coude et le genou","Les sacro-iliaques"],"r":[0,1,2,3],"e":"Orteils et doigts, tibio-tarsienne, poignet, coude et genou. Les sacro-iliaques sont le point de départ de la spondylarthrite ankylosante.","s":7},{"q":"Quels facteurs aggravent la goutte ?","o":["Obésité","Consommation d'alcool","Alimentation riche en purines","Diabète, HTA, lithiase rénale, athérosclérose","Excès d'exercice physique","Alimentation pauvre en protéines animales"],"r":[0,1,2,3,4],"e":"Tous ces facteurs sont cités comme aggravants, avec les drogues, sur un terrain héréditaire.","s":7},{"q":"Comment évoluent les crises de goutte dans le temps ?","o":["Elles surviennent plus fréquemment, mettent plus de temps à régresser et cessent d'avoir une résolution spontanée","Elles s'espacent progressivement jusqu'à disparaître","Elles gardent toujours le même profil","Elles guérissent après le troisième épisode"],"r":0,"e":"Les crises suivantes sont plus fréquentes, plus longues à régresser et perdent leur résolution spontanée. La goutte ne guérit pas.","s":7},{"q":"Quels signes accompagnent une crise de goutte ?","o":["Douleur intense","Chaleur et rougeur","Œdème","Fièvre modérée","Desquamation cutanée locale","Déformation permanente de l'articulation dès la première crise"],"r":[0,1,2,3,4],"e":"Les cinq éléments composent le tableau de la crise, qui se résout spontanément en 3 à 10 jours au début.","s":7},{"q":"Quelles structures sont atteintes dans la spondylarthrite ankylosante ?","o":["La synoviale, la capsule, les ligaments et les tendons","Les articulations sacro-iliaques, qui fusionnent","La symphyse pubienne, les costo-vertébrales et la manubrio-sternale","Uniquement les disques intervertébraux"],"r":[0,1,2],"e":"Synoviale, capsule, ligaments et tendons, avec ponts osseux et syndesmophytes, fusion des sacro-iliaques et ankylose de la symphyse pubienne, des costo-vertébrales et de la manubrio-sternale. S'y ajoute une ostéoporose.","s":7},{"q":"Quel est le pronostic évolutif de la spondylarthrite ankylosante ?","o":["Début variable et insidieux, schéma cyclique, incapacité progressive, mais espérance de vie préservée","Évolution rapide vers le décès","Guérison spontanée fréquente","Absence totale d'incapacité"],"r":0,"e":"Début insidieux, schéma cyclique, incapacité progressive, mais la maladie ne compromet pas l'espérance de vie : le pronostic est bon.","s":7},{"q":"Quelles sont les composantes du diagnostic de fibromyalgie ?","o":["Symptomatologie physique, cognitive et émotionnelle","Au moins 11 des 18 points douloureux à la pression digitale bilatérale","Absence de facteurs rhumatoïdes","Présence de syndesmophytes"],"r":[0,1,2],"e":"Symptomatologie physique, cognitive et émotionnelle, au moins 11/18 points douloureux, et absence de facteurs rhumatoïdes.","s":7},{"q":"Quelles interventions sont proposées dans la fibromyalgie ?","o":["Exercice","Pharmacothérapie : antalgiques, myorelaxants, antidépresseurs","Éducation et conseil","Soutien psychologique","Immobilisation des zones douloureuses"],"r":[0,1,2,3],"e":"Exercice, pharmacothérapie, éducation et soutien psychologique. L'immobilisation n'est pas indiquée.","s":7},{"q":"Comment l'ostéoporose est-elle habituellement découverte ?","o":["Elle est asymptomatique et détectée par densitométrie osseuse, ou révélée par une fracture pour traumatisme minime","Par une douleur osseuse constante","Par un bilan inflammatoire perturbé","Par une raideur matinale prolongée"],"r":0,"e":"L'ostéoporose est asymptomatique : elle est détectée par densitométrie, ou révélée par des fractures pour traumatismes minimes voire spontanées, une déformation du rachis et une perte de taille.","s":7},{"q":"Quel est le mécanisme de l'ostéoporose de type II ?","o":["Diminution de la formation osseuse, hyperparathyroïdie secondaire et diminution de l'absorption intestinale du calcium","Diminution de la production d'œstrogènes","Mécanisme multifactoriel chez le jeune adulte","Excès d'activité ostéoblastique"],"r":0,"e":"Type I (post-ménopause) : chute des œstrogènes. Type II (après 65 ans) : baisse de la formation osseuse, hyperparathyroïdie secondaire, malabsorption calcique. Type III (jeune adulte) : multifactoriel.","s":7},{"q":"Quelles mesures composent l'intervention dans l'ostéoporose ?","o":["Alimentation riche en calcium et vitamine D","Éviter l'excès de caféine et d'alcool","Exercice physique","Traitement substitutif et ajustement des médicaments","Repos strict pour éviter les fractures"],"r":[0,1,2,3],"e":"Alimentation, limitation de la caféine et de l'alcool, exercice (qui stimule les ostéoblastes et prévient les chutes), traitement substitutif et ajustement médicamenteux.","s":7},{"q":"Quelles adaptations de l'exercice s'imposent en cas d'artériopathie périphérique diabétique ?","o":["Plusieurs périodes de repos ou alternance d'activités","Natation, vélo d'appartement, tapis roulant, exercices en chaîne cinétique ouverte","Soin attentif des pieds","Entraînement de force à charges élevées"],"r":[0,1,2],"e":"L'artériopathie impose des pauses ou une alternance d'activités et un soin des pieds, du fait de la claudication douloureuse. Les charges élevées sont à éviter dans la rétinopathie.","s":7},{"q":"Comment l'OMS définit-elle l'activité physique ?","o":["Tout mouvement corporel produit par le système squelettique qui requiert une dépense d'énergie","Un mouvement planifié, structuré et répétitif","Une pratique sportive de compétition","Une activité de loisir uniquement"],"r":0,"e":"C'est la définition de l'OMS (2022) ; l'exercice physique en est une sous-catégorie.","s":8},{"q":"Quels sont les quatre qualificatifs de l'exercice physique selon l'ACSM ?","o":["Planifié, structuré, répétitif et intentionnel","Intense, long, varié et ludique","Aérobie, anaérobie, statique et dynamique","Analytique, global, passif et actif"],"r":0,"e":"L'ACSM (2019) définit l'exercice comme planifié, structuré, répétitif et intentionnel.","s":8},{"q":"Quelles composantes constituent la condition physique liée à la santé ?","o":["Force, flexibilité, capacité aérobie et composition corporelle","Coordination, agilité, vitesse et équilibre","Puissance, endurance, souplesse et détente","Mobilité, stabilité, endurance et posture"],"r":0,"e":"L'exercice est orienté vers le maintien d'habiletés et de la condition physique liée à la santé : force, flexibilité, capacité aérobie et composition corporelle.","s":8},{"q":"Quelle modification à long terme découle de l'exercice physique ?","o":["L'augmentation de la taille et du volume du tissu contractile","La diminution de l'apport sanguin","La perte de coordination motrice","La disparition des adaptations biochimiques"],"r":0,"e":"À long terme : taille/volume du tissu contractile, apport sanguin, coordination motrice et modifications biochimiques.","s":8},{"q":"Quel défi lié au patient est cité dans la prescription d'exercice ?","o":["L'adhésion, limitée par la douleur, la fatigue et la kinésiophobie","Le coût du matériel","La disponibilité des salles","La durée des séances"],"r":0,"e":"Les trois défis cités sont le raisonnement clinique, l'adhésion du patient (douleur, fatigue, kinésiophobie) et les guidelines.","s":8},{"q":"Dans le modèle de gestion du patient, que vient-il juste après l'évaluation ?","o":["La hiérarchisation des principaux problèmes","Le pronostic","L'intervention","L'examen subjectif"],"r":0,"e":"Examen → Évaluation → Hiérarchisation des problèmes → Diagnostic → Pronostic → Intervention, avec réévaluation constante.","s":8},{"q":"Quel élément du modèle de Hall & Brody est décrit comme « constant » ?","o":["La réévaluation","L'examen objectif","Le diagnostic","Le pronostic"],"r":0,"e":"La réévaluation est constante tout au long du processus.","s":8},{"q":"Quel principe décrit la perte des gains à l'arrêt de la stimulation ?","o":["La réversibilité","La spécificité","La surcharge","L'adaptation"],"r":0,"e":"La réversibilité traduit la perte des adaptations lorsque le stimulus cesse.","s":8},{"q":"Quel principe impose de dépasser le niveau habituel de sollicitation ?","o":["La surcharge","La progression","La régularité","L'individualisation"],"r":0,"e":"La surcharge est le principe qui déclenche l'adaptation.","s":8},{"q":"Quel principe justifie d'adapter la prescription aux objectifs propres de la personne ?","o":["L'individualisation","La spécificité","La variabilité","La progression"],"r":0,"e":"Le principe d'individualisation impose de ne pas oublier les objectifs de la personne elle-même.","s":8},{"q":"Que signifie l'acronyme FITT ?","o":["Fréquence, Intensité, Temps, Type","Force, Intensité, Tempo, Technique","Flexibilité, Instabilité, Tonus, Travail","Fonction, Impact, Tolérance, Terrain"],"r":0,"e":"FITT = Fréquence, Intensité, Temps (durée) et Type.","s":8},{"q":"Quelle variable ne fait PAS partie des variables complémentaires de prescription ?","o":["La température ambiante","Les séries","Les répétitions","L'intervalle de repos"],"r":0,"e":"Les variables complémentaires citées sont : séries, répétitions, intervalle de repos, continu ou alterné.","s":8},{"q":"Quel paramètre permet de faire progresser le degré de difficulté d'un exercice ?","o":["Le bras de levier","La couleur du matériel","L'horaire de la séance","Le nombre de thérapeutes"],"r":0,"e":"Progression par : pesanteur, bras de levier, charge, amplitudes de mouvement et vitesse.","s":8},{"q":"Combien de piliers compte l'exercice thérapeutique ?","o":["5","3","4","7"],"r":0,"e":"Mobilité, flexibilité, force musculaire, reprogrammation sensori-motrice et pliométrie.","s":8},{"q":"Sur quoi la mobilité a-t-elle des effets directs ?","o":["Sur la physiologie articulaire","Sur la fibre musculaire","Sur les récepteurs sensori-moteurs","Sur la puissance"],"r":0,"e":"La mobilité vise l'amplitude articulaire avec des effets directs sur la physiologie articulaire.","s":8},{"q":"Sur quoi la flexibilité a-t-elle des effets directs ?","o":["Sur la fibre musculaire","Sur la physiologie articulaire","Sur le système cardio-respiratoire","Sur la composition corporelle"],"r":0,"e":"Mobilité → physiologie articulaire ; flexibilité → fibre musculaire. C'est la distinction clé entre les deux piliers.","s":8},{"q":"Sur quoi la reprogrammation sensori-motrice a-t-elle des effets directs ?","o":["Sur les récepteurs sensori-moteurs","Sur la fibre musculaire","Sur le tissu osseux","Sur la capacité aérobie"],"r":0,"e":"La RSM vise la qualité du mouvement, avec des effets directs sur les récepteurs sensori-moteurs.","s":8},{"q":"Que vise la pliométrie ?","o":["La puissance, l'agilité et la vitesse","L'amplitude articulaire","La composition corporelle","La lubrification articulaire"],"r":0,"e":"La pliométrie vise à maintenir ou améliorer la puissance, l'agilité et la vitesse.","s":8},{"q":"Quelle sensation doit induire un étirement ?","o":["Un inconfort, et non une douleur","Une douleur vive","Aucune sensation","Une brûlure intense"],"r":0,"e":"L'étirement doit induire un inconfort et non une douleur.","s":8},{"q":"Quelles conditions favorisent un travail de flexibilité efficace ?","o":["Patient détendu, postures équilibrées et confortables, température adéquate","Patient en contraction maximale","Environnement froid","Postures asymétriques"],"r":0,"e":"Le patient doit être détendu, dans des postures équilibrées et confortables, avec des conditions de température adéquates.","s":8},{"q":"Quels types d'étirements sont possibles ?","o":["Statiques, dynamiques, passifs ou actifs","Uniquement statiques","Uniquement passifs","Uniquement balistiques"],"r":0,"e":"Les exercices de flexibilité peuvent être statiques, dynamiques, passifs ou actifs.","s":8},{"q":"Quels sont les 3 moments d'une séance de travail de force ?","o":["Échauffement, travail de force, retour au calme","Étirement, force, étirement","Évaluation, exercice, réévaluation","Mobilité, force, pliométrie"],"r":0,"e":"La séance contient toujours ces trois moments distincts.","s":8},{"q":"Quel modèle structure les étapes du travail de force ?","o":["Le modèle OPT (NASM, 2021)","Le modèle FITT","Le modèle de Hall & Brody","Le modèle PEACE & LOVE"],"r":0,"e":"Le modèle OPT (NASM, 2021) organise plusieurs étapes travaillant des caractéristiques différentes.","s":8},{"q":"Que doit-on introduire graduellement en reprogrammation sensori-motrice ?","o":["Différents niveaux d'instabilité","Des charges maximales","Des amplitudes extrêmes","Des vitesses explosives"],"r":0,"e":"On introduit graduellement différents niveaux d'instabilité, en fournissant une stimulation adaptée au système sensori-moteur.","s":8},{"q":"Sous quelles formes la RSM peut-elle être travaillée ?","o":["Statique, dynamique et fonctionnelle","Uniquement dynamique","Uniquement en charge","Uniquement passive"],"r":0,"e":"La RSM se travaille en statique, en dynamique et en fonctionnel.","s":8},{"q":"Quel mécanisme physiologique la pliométrie active-t-elle ?","o":["Le cycle étirement/raccourcissement","Le réflexe myotatique inverse seul","La sommation temporelle","La plasticité corticale"],"r":0,"e":"La pliométrie repose sur l'activation du cycle étirement/raccourcissement : pré-étirement puis contraction explosive.","s":8},{"q":"Quels sont les prérequis avant de débuter la pliométrie ?","o":["Segment sans œdème ni douleur, avec amplitude, force et flexibilité normales","Force à 50 % du côté sain","Amplitude limitée mais indolore","Œdème modéré toléré"],"r":0,"e":"Le segment concerné doit être sans œdème ni douleur, avec amplitude articulaire, force et flexibilité normales.","s":8},{"q":"Quels principes d'apprentissage moteur faut-il concilier ?","o":["L'apprentissage par la répétition et l'adaptation par la variabilité de la tâche","La répétition seule","La variabilité seule","La vitesse et la charge uniquement"],"r":0,"e":"Il faut respecter les principes de l'apprentissage par la répétition mais aussi de l'adaptation par la variabilité de la tâche.","s":8},{"q":"Dans la gonarthrose, quels piliers sont travaillés à court terme (4-6 semaines) ?","o":["Mobilité, flexibilité et RSM","Force musculaire et pliométrie","Pliométrie seule","Force musculaire uniquement"],"r":0,"e":"Court terme : mobilité, flexibilité, RSM. Moyen terme : mobilité, FM, RSM. Long terme : FM, RSM, pliométrie.","s":8},{"q":"À quel horizon la pliométrie est-elle introduite dans la prise en charge de la gonarthrose ?","o":["À long terme (12-24 semaines)","À court terme (4-6 semaines)","À moyen terme (6-12 semaines)","Dès la première séance"],"r":0,"e":"La pliométrie n'apparaît qu'à long terme, entre 12 et 24 semaines.","s":8},{"q":"Quelles activités entrent dans la définition de l'activité physique selon l'OMS ?","o":["Les loisirs","Le mode de déplacement","L'activité professionnelle","Les tâches domestiques","Uniquement les séances structurées"],"r":[0,1,2,3],"e":"L'activité physique englobe tout mouvement corporel avec dépense d'énergie : loisirs, déplacements, travail, tâches domestiques — et l'exercice, qui n'en est qu'une sous-catégorie.","s":8},{"q":"Vers quoi l'exercice physique est-il orienté selon l'ACSM ?","o":["Le maintien d'habiletés : coordination, agilité, vitesse","La condition physique liée à la santé","La seule perte de poids","La seule performance compétitive"],"r":[0,1],"e":"L'exercice vise le maintien d'habiletés (coordination, agilité, vitesse) et de la condition physique liée à la santé : force, flexibilité, capacité aérobie, composition corporelle.","s":8},{"q":"Quelles modifications cardio-respiratoires découlent de l'exercice physique ?","o":["Aérobie","Anaérobie","Contraction de fibres rapides et lentes","Modifications des tissus conjonctifs"],"r":[0,1,2],"e":"Les modifications cardio-respiratoires regroupent aérobie, anaérobie et contraction de fibres rapides et lentes. Composition corporelle et tissus conjonctifs relèvent des modifications induites par l'entraînement.","s":8},{"q":"Quels sont les trois défis identifiés pour le kinésithérapeute qui prescrit de l'exercice ?","o":["Le raisonnement clinique","L'adhésion du patient","Les guidelines et le niveau de preuve","Le coût du matériel"],"r":[0,1,2],"e":"Raisonnement clinique, adhésion du patient (douleur, fatigue, kinésiophobie) et travail au meilleur niveau de preuve disponible.","s":8},{"q":"Dans le modèle de Hall & Brody, quelles sont les deux composantes de l'examen ?","o":["Subjectif","Objectif","Radiologique","Biologique"],"r":[0,1],"e":"L'examen comporte un volet subjectif et un volet objectif, avant l'évaluation, la hiérarchisation, le diagnostic, le pronostic et l'intervention.","s":8},{"q":"Que recouvre l'étape d'évaluation dans le modèle de gestion du patient ?","o":["L'interprétation des données, le cadre de la CIF et le tableau physiopathologique","La seule mesure de la douleur","La rédaction du compte rendu","Le choix du matériel"],"r":0,"e":"L'évaluation consiste à interpréter les données, dans le cadre de la CIF et du tableau physiopathologique.","s":8},{"q":"Quel principe explique que les adaptations dépendent du type de stimulus appliqué ?","o":["La spécificité","La surcharge","La progression","L'adaptation"],"r":0,"e":"Le principe de spécificité : les adaptations obtenues sont spécifiques du stimulus appliqué.","s":8},{"q":"Quelles sont les deux notions complémentaires aux six principes de l'exercice ?","o":["La régularité","La variabilité","La rapidité","La symétrie"],"r":[0,1],"e":"Aux six principes (surcharge, spécificité, progression, réversibilité, adaptation, individualisation) s'ajoutent la régularité et la variabilité.","s":8},{"q":"Quels paramètres permettent de faire progresser le degré de difficulté d'un exercice ?","o":["La pesanteur","Le bras de levier","La charge","Les amplitudes de mouvement","La vitesse","Le nombre de séries hebdomadaires"],"r":[0,1,2,3,4],"e":"Cinq leviers de progression : pesanteur, bras de levier, charge, amplitudes et vitesse.","s":8},{"q":"Quelle est la différence entre mobilité et flexibilité ?","o":["La mobilité agit sur la physiologie articulaire, la flexibilité sur la fibre musculaire","La mobilité agit sur la fibre musculaire, la flexibilité sur l'articulation","Les deux agissent sur le système neuromusculaire","Les deux visent la puissance"],"r":0,"e":"Les deux visent l'amplitude articulaire, mais la mobilité a des effets directs sur la physiologie articulaire et la flexibilité sur la fibre musculaire.","s":8},{"q":"Quelles idées clés caractérisent le travail de mobilité ?","o":["Mouvement libre et qualité du schéma de mouvement","Amplitude de mouvement","Mouvement analytique et fonctionnel","Mouvement général et spécifique","Contraction explosive"],"r":[0,1,2,3],"e":"Mouvement libre, qualité du schéma, amplitude, analytique et fonctionnel, général et spécifique, et répétition. La contraction explosive relève de la pliométrie.","s":8},{"q":"Quelles conditions favorisent une séance de flexibilité efficace ?","o":["Patient détendu","Postures corporelles équilibrées et confortables","Température adéquate","Étirement poussé jusqu'à la douleur"],"r":[0,1,2],"e":"Patient détendu, postures équilibrées et confortables, température adéquate. L'étirement doit induire un inconfort, jamais une douleur.","s":8},{"q":"Que précède obligatoirement le travail de force dans une séance ?","o":["L'échauffement","Le retour au calme","La pliométrie","L'évaluation radiographique"],"r":0,"e":"La séance de force comporte toujours trois moments : échauffement, travail de force adapté à l'objectif, puis retour au calme.","s":8},{"q":"Que faut-il réaliser avant d'engager un travail de force ?","o":["Une évaluation de la force","Une radiographie","Un test d'effort maximal","Une séance de pliométrie"],"r":0,"e":"L'évaluation de la force est un préalable, et le travail se structure ensuite en plusieurs étapes selon le modèle OPT (NASM, 2021).","s":8},{"q":"Quelles idées clés structurent la reprogrammation sensori-motrice ?","o":["Introduction graduelle de différents niveaux d'instabilité","Répétition contre variabilité","Contrôle du schéma et de la qualité du mouvement","Travail statique, dynamique et fonctionnel","Contraction excentrique maximale"],"r":[0,1,2,3],"e":"Instabilité graduée, dialectique répétition/variabilité, contrôle de la qualité du mouvement, et déclinaison statique, dynamique et fonctionnelle.","s":8},{"q":"Sur quel mécanisme repose la pliométrie ?","o":["Un pré-étirement du muscle suivi d'une contraction explosive, activant le cycle étirement/raccourcissement","Une contraction isométrique prolongée","Un étirement passif maintenu","Une contraction concentrique lente"],"r":0,"e":"La pliométrie active le cycle étirement/raccourcissement : pré-étirement puis contraction explosive.","s":8},{"q":"Quels prérequis sont exigés avant de débuter la pliométrie ?","o":["Segment sans œdème","Segment sans douleur","Amplitude articulaire normale","Force et flexibilité normales","Un âge inférieur à 40 ans"],"r":[0,1,2,3],"e":"Le segment doit être sans œdème ni douleur, avec amplitude, force et flexibilité normales.","s":8},{"q":"Quelles recommandations générales encadrent la prescription d'exercice ?","o":["Ne pas oublier les objectifs, surtout ceux de la personne","Évaluer et réévaluer","Travailler avec le meilleur niveau de preuve disponible","Être créatif, avec mesure","Standardiser le protocole pour tous les patients"],"r":[0,1,2,3],"e":"Individualisation, réévaluation, meilleur niveau de preuve et créativité mesurée. La standardisation contredit le principe d'individualisation.","s":8},{"q":"Dans la gonarthrose, quels problèmes la prescription d'exercice va-t-elle cibler ?","o":["Diminution du ROM","Diminution de la flexibilité","Diminution de la force musculaire","Difficulté à la marche et à l'appui des membres inférieurs","Déformation osseuse irréversible"],"r":[0,1,2,3],"e":"Quatre problèmes accessibles à l'exercice : ROM, flexibilité, force et difficulté de marche/appui.","s":8},{"q":"Dans la gonarthrose, quels piliers sont travaillés à moyen terme (6-12 semaines) ?","o":["Mobilité, force musculaire et RSM","Mobilité, flexibilité et RSM","Force musculaire, RSM et pliométrie","Pliométrie seule"],"r":0,"e":"Court terme (4-6 sem.) : mobilité, flexibilité, RSM. Moyen terme (6-12 sem.) : mobilité, force, RSM. Long terme (12-24 sem.) : force, RSM, pliométrie.","s":8}]};
